(function()
{
    IMu.Storage = {};

    var str = IMu.URL.path + '/' + IMu.path + '/..';
    str = str.replace(/^https?:\/\/[^\/]*\//, '');
    IMu.log('Storage str "{0}"', str);
    var old = str.split(/\//);
    var fix = [];
    for (var i = 0; i < old.length; i++)
    {
        if (old[i] != '..')
            fix.push(old[i]);
        else if (fix.length > 0)
            fix.pop();
    }
    IMu.Storage.path = '/' + fix.join('/');
    IMu.log('Storage.path {0}', IMu.Storage.path);

    /*!
    */
    IMu.Storage.Cookie =
    {
        /* These methods are based on the cookie reader/writer descibed in
        ** https://developer.mozilla.org/en-US/docs/Web/API/document.cookie
        */

        /*!
        ** Gets the value of a cookie.
        **
        ** If the named cookie does not exist the a copy of the $<_default>
        ** parameter is returned instead.
        **
        ** @param name string
        **   The name of the cookie.
        ** 
        ** @param _default mixed
        **   The default value to be returned if the cookie does not exist.
        **   If the value is an object a deep copy is returned.
        **
        ** @returns mixed
        **   The value of the named cookie or the default value.
        */
        get: function(name, _default)
        {
            IMu.log('Storage.Cookie.get: name {0}', name);

            var key = window.encodeURIComponent(name);
            key = key.replace(/[\-\.\+\*]/g, "\\$&");

            var regex = new RegExp('(^|;)\\s*' + key + '\\s*\\=\\s*([^;]*)');

            var match = document.cookie.match(regex);
            var value;
            if (match)
                value = JSON.parse(window.decodeURIComponent(match[2]));
            else
                value = IMu.Object.copy(_default);

            IMu.log('Storage.Cookie.get: value {0}', value);
            return value;
        },

        /*!
        ** Checks for whether a particular cookie exists.
        **
        ** @param name string
        **   The name of the cookie.
        **
        ** @returns boolean
        **   **true** if the cookie exists, **false** otherwise.
        */
        has: function(name)
        {
            IMu.log('Storage.Cookie.has: name {0}', name);

            var key = window.encodeURIComponent(name);
            key = key.replace(/[\-\.\+\*]/g, "\\$&");

            var regex = new RegExp('(^|;)\\s*' + key + '\\s*\\=');

            var match = document.cookie.match(regex);
            var result = match != null;

            IMu.log('Storage.Cookie.has: result {0}', result);
            return result;
        },

        /*!
        ** Generate a list of names of all cookies.
        **
        ** Note: certain cookies such as __utma, __utmb and so on which are
        ** used by Google Analytics are ignored.
        **
        ** @returns array
        **   The list of cookie names.
        */
        list: function()
        {
            var names = [];

            var cookie = document.cookie;
            IMu.log('Storage.Cookie.list: cookie {0}', cookie);
            for (;;)
            {
                var match = cookie.match(/^\s*(\S[^=]*)\s*=[^;]*;?(.*)$/);
                if (! match)
                    break;

                var name = match[1];

                /* Ignore special google cookies */
                if (! name.match(/^__utm.$/))
                    names.push(name);

                cookie = match[2];
            }

            return names;
        },

        /*!
        ** Removes a cookie.
        **
        ** @param name string
        **   The name of the cookie.
        */
        remove: function(name)
        {
            if (name === undefined)
                return false;

            if (! this.has(name))
                return false;

            var key = window.encodeURIComponent(name);
            key = key.replace(/[\-\.\+\*]/g, "\\$&");

            var cookie = key + '=';
            cookie += ';expires=Thu, 01 Jan 1970 00:00:00 GMT';
            cookie += ';path=' + IMu.Storage.path;
            IMu.log('Storage.Cookie.remove: cookie {0}', cookie);

            /* TODO: if cookie is empty, remove entirely
            */
            document.cookie = cookie;

            return true;
        },

        /*!
        ** Sets the value of a cookie.
        **
        ** Values are serialised as JSON and then URI encoded.
        **
        ** @param name string
        **   The name of the cookie.
        **
        ** @param value mixed
        **   The value of the cookie.
        **
        ** @param expires mixed
        **   When the cookie should be expired.
        **
        **   This value can be a:
        **
        **   * date
        **     The cookie is set to expire at the given date and time.
        **
        **   * number
        **     The cookie is set to expire after the given period.
        **
        **     A special value of *Infinity* may be used to ensure
        **     the cookie does not expire (the expiry date is set to
        **     31 December 9999).
        **
        **   * string
        **     The string can be a number followed by:
        **
        **     * s (seconds)
        **     * m (minutes)
        **     * h (hours)
        **     * d (days)
        **     * w (weeks)
        **
        **     Otherwise, the expiry date is set directly from the given string.
        **     It is assumed that the string is in a format which is understood
        **     by the browser as a date.
        **
        ** @returns boolean
        **   An indication of whether the cookie was set successfully or not.
        */
        set: function(name, value, expires)
        {
            IMu.log('Storage.Cookie.set: name {0}', name);
            IMu.log('Storage.Cookie.set: value {0}', value);
            IMu.log('Storage.Cookie.set: expires {0}', expires);

            if (name === undefined)
                return false;

            if (/^(?:expires|max\-age|path|domain|secure)$/i.test(name))
                return false;

            var key = window.encodeURIComponent(name);

            value = window.encodeURIComponent(JSON.stringify(value));

            switch (IMu.Type.get(expires))
            {
              case 'date':
                expires = expires.toUTCString();
                break;

              case 'number':
                if (expires === Infinity)
                    expires = 'Fri, 31 Dec 9999 23:59:59 UTC';
                else
                {
                    var time = new Date(Date.now() + expires * 1000);
                    expires = time.toUTCString();
                }
                break;

              case 'string':
                var match = expires.match(/^(\d+(\.\d+)?)\s*([smhdw])/);
                if (match)
                {
                    var secs = match[1];

                    /* Note: all cases are *meant* to fall through! */
                    switch (match[3])
                    {
                      case 'w':
                        secs *= 7;
                      case 'd':
                        secs *= 24;
                      case 'h':
                        secs *= 60;
                      case 'm':
                        secs *= 60;
                    }

                    var time = new Date(Date.now() + secs * 1000);
                    expires = time.toUTCString();
                }
                /* otherwise assume valid date string! */
                break;

              default:
                expires = undefined;
                break;
            }

            var cookie = key + '=' + value;
            cookie += ';path=' + IMu.Storage.path;
            if (expires)
                cookie += ';expires=' + expires;
            IMu.log('Storage.Cookie.set: cookie {0}', cookie);

            document.cookie = cookie;

            return true;
        }
    };

    if (typeof(window.localStorage) != 'undefined')
    {
        /*!
        */
        IMu.Storage.Local =
        {
            html5: true,

            /*!
            ** Gets a variable from local storage.
            **
            ** If the variable does not exist the a copy of the $<_default>
            ** parameter is returned instead.
            **
            ** @param name string
            **   The name of the variable.
            ** 
            ** @param _default mixed
            **   The default value to be returned if the variable does not
            **   exist. If the value is an object a deep copy is returned.
            **
            ** @returns mixed
            **   The value of the variable or the default value.
            */
            get: function(name, _default)
            {
                var key = IMu.Storage.path + '/' + name;
                if (key in window.localStorage)
                    return JSON.parse(window.localStorage.getItem(key));
                return IMu.Object.copy(_default);
            },

            has: function(name)
            {
                var key = IMu.Storage.path + '/' + name;
                return key in window.localStorage;
            },

            remove: function(name)
            {
                var key = IMu.Storage.path + '/' + name;
                window.localStorage.removeItem(key);
            },

            set: function(name, value)
            {
                var key = IMu.Storage.path + '/' + name;
                window.localStorage.setItem(key, JSON.stringify(value));
            }
        };
    }
    else
    {
        /* These methods are fallbacks for those documented above on certain
        ** older platforms.
        */
        IMu.Storage.Local =
        {
            html5: false,

            get: function(name, _default)
            {
                return IMu.Storage.Cookie.get(name, _default);
            },

            has: function(name)
            {
                return IMu.Storage.Cookie.has(name);
            },

            remove: function(name)
            {
                IMu.Storage.Cookie.remove(name);
            },

            set: function(name, value)
            {
                IMu.Storage.Cookie.set(name, value, Infinity);
            }
        };
    }

    if (typeof(window.sessionStorage) != 'undefined')
    {
        /*!
        */
        IMu.Storage.Session =
        {
            html5: true,

            /*!
            ** Gets a variable from session storage.
            **
            ** If the variable does not exist the a copy of the $<_default>
            ** parameter is returned instead.
            **
            ** @param name string
            **   The name of the variable.
            ** 
            ** @param _default mixed
            **   The default value to be returned if the variable does not
            **   exist. If the value is an object a deep copy is returned.
            **
            ** @returns mixed
            **   The value of the variable or the default value.
            */
            get: function(name, _default)
            {
                var key = IMu.Storage.path + '/' + name;
                if (key in window.sessionStorage)
                    return JSON.parse(window.sessionStorage.getItem(key));
                return IMu.Object.copy(_default);
            },

            has: function(name)
            {
                var key = IMu.Storage.path + '/' + name;
                return key in window.sessionStorage;
            },

            remove: function(name)
            {
                var key = IMu.Storage.path + '/' + name;
                window.sessionStorage.removeItem(key);
            },

            set: function(name, value)
            {
                var key = IMu.Storage.path + '/' + name;
                window.sessionStorage.setItem(key, JSON.stringify(value));
            }
        };
    }
    else
    {
        /* These methods are fallbacks for those documented above on certain
        ** older platforms.
        */
        IMu.Storage.Session =
        {
            html5: false,

            get: function(name, _default)
            {
                return IMu.Storage.Cookie.get(name, _default);
            },

            has: function(name)
            {
                return IMu.Storage.Cookie.has(name);
            },

            remove: function(name)
            {
                IMu.Storage.Cookie.remove(name);
            },

            set: function(name, value)
            {
                IMu.Storage.Cookie.set(name, value);
            }
        };
    }
})();

/* Source: ./utils/common/Login.js
*/
(function()
{
    IMu.Login =
    {
        info: IMu.Cookies.get().values.login,

        login: function(username, password, group, service, callback)
        {
            var self = this;

            if (typeof(group) == 'function')
            {
                callback = group;
                group = undefined;
            }
            // service is optional
            if (typeof(service) == 'function')
            {
                callback = service;
                service = undefined;
            }

            var request = new IMu.Request.Login();
            request.onComplete = function(result)
            {
                IMu.log('Login.login: success {0}', result.success);
                if (! result.success)
                    IMu.Cookies.get().remove();
                else
                {
                    var info = {};

                    var response = result.response;
                    info.port = response.port;
                    info.context = response.context;

                    if (response.result)
                    {
                        for (var name in response.result)
                            info[name] = response.result[name];
                    }
					IMu.log('Login.login: info {0}', info);

                    var cookie = IMu.Cookies.get();
                    cookie.values.login = info;
                    cookie.save();

                    self.info = IMu.Cookies.get().values.login;
                }
                if (callback)
                    callback.call(self, result);
            };
            IMu.log('Login.login: logging in as {0}...', username);
            request.login(username, password, group, service);
        },

        logout: function(callback)
        {
            var self = this;

            var request = new IMu.Request.Login();
            request.onComplete = function(result)
            {
                IMu.log('Login.logout: success {0}', result.success);
                var cookie = IMu.Cookies.get();
                cookie.values.login = undefined;
                cookie.save();

                self.info = undefined;
                
                if (callback)
                    callback.call(self, result);
            };
            IMu.log('Login.logout: logging out...');
            request.logout(self.info.port, self.info.context);
        },

        checkStatus: function(interval, callback)
        {
            var self = this;

            if (! (self.info && self.info.port && self.info.context) ||
                typeof(interval) != 'number') // ...Means we can skip entirely
                return;
           
            // Check at least once
            var request = new IMu.Request.Login();
            request.onComplete = function(result)
            {
                if (callback)
                {
                    if (result.success)
                        callback.call(self, true, result.response.result);
                    else
                        callback.call(self, false, result.response);
                }
            }
            request.checkStatus(self.info.port, self.info.context);

            // Successive checks
            if (interval > 0)
            {
                interval *= 60000;   // milliseconds to minutes

                var intervalID = setInterval(function()
                {
                    var request = new IMu.Request.Login();
                    request.onComplete = function(result)
                    {
                        if (callback)
                        {
                            if (result.success)
                                callback.call(self, true, result.response.result);
                            else
                                callback.call(self, false, result.response);
                        }
                    }
                    request.checkStatus(self.info.port, self.info.context);
                }, interval);
           }     
        }
    };
IMu.log('IMu.Login.info {0}', IMu.Login.info);
})();

/* Source: ./utils/common/Terms.js
*/
IMu.Terms = IMu.Class.create
({
    _construct: function(kind)
    {
        if (! kind)
            kind = 'and';
        else
            kind = kind.toLowerCase();
        if (kind != 'and' && kind != 'or')
            throw new IMu.Error('TermsIllegalKind', kind);
        this.kind = kind;
        this.list = [];
    },

    getKind: function()
    {
        return this.kind;
    },

    getList: function()
    {
        return this.list;
    },

    add: function(name, value, op)
    {
        var term = [name, value, op];
        this.list.push(term);
    },

    addTerms: function(kind)
    {
        var child = new IMu.Terms(kind);
        this.list.push(child);
        return child;
    },

    addAnd: function()
    {
        return this.addTerms('and');
    },

    addOr: function()
    {
        return this.addTerms('or');
    },

    toArray: function()
    {
        var result = [];
        result[0] = this.kind;

        var list = [];
        for (var i = 0; i < this.list.length; i++)
        {
            var term = this.list[i];
            if (term instanceof IMu.Terms)
                term = term.toArray();
            list.push(term);
        }
        result[1] = list;

        return result;
    }
});

/* Source: ./utils/common/Themes.js
*/
IMu.Themes =
{
	shared: undefined,

	registered: {},
	current: undefined,

	add: function(name)
	{
        var theme = new IMu.Theme(name);
        this.registered[name] = theme;
        return theme;
    },

    get: function(name)
    {
        return this.registered[name];
    },

	select: function(name, callback)
	{
		IMu.log('Themes.select: name {0}', name);
		if (this.current && this.current.name == name)
		{
			IMu.log('Themes.select: already selected');
            if (callback)
                callback();
			return;
		}

		var theme = this.registered[name];
		if (! theme)
			throw new IMu.Error('ThemesUnknownTheme', name);

		if (this.current)
		{
			this.current.deactivate();
			this.current = undefined;
		}
//		this.shared.activate();
//      theme.load(function()
//      {
            this.current = theme;
            this.current.activate();
            if (callback)
                callback();
//      });
	},

	// convenience
	string: function(id)
	{
		var string = this.current.strings.get(id);
		if (! string)
        {
            string = this.shared.strings.get(id);
            if (! string)
                string = id;
        }
        if (arguments.length > 1)
        {
            var params = Array.prototype.slice.call(arguments, 1);
            string = IMu.Format.formatParams(string, params);
        }
		return string;
	},

	// private
	update: function()
	{
//		this.shared.update();
        if (this.current)
            this.current.update();
	}
};

/* ... for convenience */
IMu.string = function(id)
{
	return IMu.Themes.string(id);
};
IMu.Events.bind('dom-orientationchange', function(name)
{
	IMu.Themes.update();
});
IMu.Events.bind('language-changed', function(name)
{
	IMu.Themes.update();
});

IMu.Theme = IMu.Class.create
({
	_construct: function(name)
	{
		this.name = name;

		this.strings = new IMu.Theme.Strings(this);
		this.css = new IMu.Theme.CSS(this);
		this.views = new IMu.Theme.Views(this);
	},

    load: null,

	activate: function()
	{
		this.css.activate();
		if (this.name != 'shared')
			IMu.Events.trigger('theme-activated', this);
	},

	deactivate: function()
	{
		this.css.deactivate();
		if (this.name != 'shared')
			IMu.Events.trigger('theme-deactivated', this);
	},

	initialise: function()
	{
	},

	update: function()
	{
		this.css.activate();
	}
});

IMu.Theme.Strings = IMu.Class.create
({
	_construct: function(theme)
	{
		this.theme = theme;
		this.set = {};
	},

	get: function(id)
	{
		if (! (id in this.set))
			return undefined;
		var lang = IMu.Languages.current.code;
		if (! (lang in this.set[id]))
            lang = lang.replace(/-[A-Z]+$/, "");    //try non-region specific
		if (! (lang in this.set[id]))
			return undefined;
		return this.set[id][lang];
	},

	register: function(set)
	{
		for (var id in set)
		{
			if (! this.set[id])
				this.set[id]  = {};
			for (var lang in set[id])
				this.set[id][lang] = set[id][lang];
		}
	}
});

IMu.Theme.CSS = IMu.Class.create
({
	_construct: function(theme)
	{
		this.theme = theme;
	},

	activate: function()
	{
        var links = jQuery('link[href*="/themes/"]');
        var pattern = /\/themes\/([a-z]+)\/css\/([^\/]+)$/;
        var sheets = [];
        for (var i = 0; i < links.length; i++)
        {
            var link = jQuery(links[i]);
            var href = link.attr('href');
            var match = href.match(pattern);
            if (! match)
                continue;
            var sheet =
            {
                link: link,
                href: href,
                theme: match[1],
                file: match[2],
                disabled: true
            };
            sheets.push(sheet);
        }
        IMu.log('Found {0} IMu-related stylesheets', sheets.length);

        var dirs = /\b(ltr|rtl)\./;
        var languages = /\b(ar|en|fr)\./;
        var orientations = /\b(landscape|portrait)\./;
        for (var i = 0; i < sheets.length; i++)
        {
            var sheet = sheets[i];

            if (sheet.theme != this.theme.name)
                continue;

            var match = sheet.file.match(dirs);
            if (match && match[1] != IMu.Languages.current.dir)
                continue;

            var match = sheet.file.match(languages);
            if (match && match[1] != IMu.Languages.current.code)
                continue;

            var match = sheet.file.match(orientations);
            if (match && match[1] != IMu.Platform.window.orientation.name)
                continue;

            sheet.disabled = false;
        }

        var enabled = 0;
        for (var i = 0; i < sheets.length; i++)
        {
            var sheet = sheets[i];
            sheet.link[0].disabled = sheet.disabled;
            IMu.log('{0}abling {1}', (sheet.disabled ? 'Dis' : 'En'), sheet.href);
            if (! sheet.disabled)
                enabled++;
        }
        IMu.log('Enabled {0} IMu-related stylesheets', enabled);
	},

	deactivate: function()
	{
        // do nothing as activate will take care of it?
	}
});

IMu.Theme.Views = IMu.Class.create
({
	_construct: function(theme)
	{
		this.theme = theme;
		this.set = {};
	},

	register: function(name)
	{
        IMu.log('{0}: Theme.Views.register: name {1}', this.theme.name, name);
        var entry = this.set[name];
		if (! entry)
        {
            entry = this.set[name] = {};
            entry.requires = {};
            entry.methods = [];
        }

        var index = 1;

        while (index < arguments.length)
        {
            if (! IMu.Type.isString(arguments[index]))
                break;
            var require = arguments[index++];
            entry.requires[require] = true;
        }

        while (index < arguments.length)
        {
            if (! IMu.Type.isObject(arguments[index]))
                break;
            var info = arguments[index++];
            for (var device in info)
            {
                if (device != 'all' && ! IMu.Platform.device.is[device])
                    continue;

                entry.methods.push(info[device]);

                /* Attach the full method name to the method!
                ** This is very useful for debugging in getMethods (see above).
                */
                var _method = info._source + '.' + device;
                for (var method in info[device])
                    info[device][method]._method = _method + '.' + method;
            }
        }
	}
});

