/*!
** Simple widget for artist searching.
**
** Creates A to Z boxes which can be used for artist searching. When
** the user presses the box the **artistSearch** event handler is 
** called.
**
** Can be used to trigger simple artist search.
**
** @since 2.0
*/

/*!
** @example
**  Create a simple A to Z artist search boxes
**
** @code
**  var widget = $('#my-div').IMu('artist-search');
*/

/*!
** @example
**  Create A to Z artist search boxes with a label
**
** @code
**  var widget = $('#my-div').IMu('artist-search',
**      {
**          showLabel: true,
**      }
**  );
*/

/*!
** @example
**  Install a callback to handle when an individual artist is clicked
**
** @code
**  var widget = $('#my-div').IMu('artist-search',
**      {
**          onSubmit: function(text)
**          {
**              alert('search for ' + text);
**          }
**      }
**  );
*/
IMu.Widgets.add('artist-search', 'base',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-artist-search');

        this.registerOptions
        ({
            /*!
            ** Specifies that a label (prompt) should be added
            **
            ** @type boolean
            */
            showLabel: false,

            /*!
            ** The user has selected an artist name
            */
            onSubmit: undefined
        });

        this.terms = '';
    },

    /*!
    ** Searches for all artist with a last name beginning with the selected 
    ** letter.
    **
    ** @param value string
    **   The letter to search on.
    **
    ** @param columns string
    **   The columns to fetch from eparties.
    **
    ** @param callback function
    **   Returns control back to the previous function.
    */
    artistSearch: function(value, columns, callback)
    {
        var self = this;

        var terms = new IMu.Terms();
        terms.add('NamLast', '\\^' + value + '\\*');
        var search = new IMu.Request.Search();
        search.search(terms, ['eparties'], function(hits)
        {
            search.sort('+NamLast', '', function()
            {  
                search.fetch('start', 0, -1, columns, function(data)
                {  
                    if (callback)
                        callback(data);
                });
            });
        });
    },

    /*!
    ** Runs a search across modules on the selected artist name.
    */
    doSubmit: function()
    {
        if (this.options.onSubmit)
            this.options.onSubmit.call(this, this.terms, this.imagesOnly);
        else if (this.options.onSearch)
            this.options.onSearch.call(this, this.terms, this.imagesOnly);
        IMu.Events.trigger('imu-search', this.terms, this.imagesOnly);
    }
});

/* Source: ./widgets/common/keyword-search.js
*/
/*!
** Simple widget for keyword searching.
**
** Creates a simple text box which can be used for keyword searching. When
** the user presses the **Enter** key (or the submit button if enabled) the
** **onSearch** event handler is called.
**
** Can be used to trigger simple database keyword search.
**
** @since 2.0
*/

/*!
** @example
**  Create a simple text box
**
** @code
**  var widget = $('#my-div').IMu('keyword-search');
*/

/*!
** @example
**  Create a text box with a label and a submit button
**
** @code
**  var widget = $('#my-div').IMu('keyword-search',
**      {
**          showLabel: true,
**          showSubmit: true
**      }
**  );
*/

/*!
** @example
**  Install a callback to handle when a search is requested
**
** @code
**  var widget = $('#my-div').IMu('keyword-search',
**      {
**          onSearch: function(terms)
**          {
**              alert('search for ' + terms);
**          }
**      }
**  );
*/
IMu.Widgets.add('keyword-search', 'base',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-keyword-search');

        this.registerOptions
        ({
            /*!
            ** Specifies that an "Only items with images" prompt
            ** should also be shown.
            **
            ** @type boolean
            */
            onlyItemsWithImages: IMu.Config.showOnlyItemsWithImages,

            /*!
            ** Specifies that a clear button should be added after the text
            ** box.
            **
            ** @type boolean
            */
            showClear: false,

            /*!
            ** Specifies that a label (prompt) should be added before the text
            ** box.
            **
            ** @type boolean
            */
            showLabel: false,

            /*!
            ** Specifies that a button should be added after the text box.
            **
            ** @type boolean
            */
            showSubmit: false,

            /*!
            ** The user has pressed the clear button.
            */
            onClear: undefined,

            /*!
            ** The user has pressed the **Enter** key or the submit button.
            **
            ** @param terms string
            **   The current search terms in the input box.
            */
            onSubmit: undefined,

            /*!
            ** Alias for onSubmit (for backwards-compatibility).
            */
            onSearch: undefined
        });

        this.terms = '';
        this.imagesOnly = false;
    },

    /*!
    ** Clears the search form.
    */
	clear: function()
	{
		if (this.view)
			this.view.clear();
	},

    /*!
    ** Get the contents of the search box.
    **
    ** @returns string
    **   The current search terms.
    */
    getTerms: function()
    {
        return this.terms;
    },

    /*!
    ** Set the terms displayed in the text box.
    **
    ** @param terms string
    **   The text to set in the text box.
    */
    setTerms: function(terms)
    {
        this.terms = terms;
        if (this.view)
            this.view.setTerms(terms);
    },

    // private
	doClear: function()
	{
		this.clear();
		if (this.options.onClear)
			this.options.onClear.call(this);
        IMu.Events.trigger('imu-clear');
	},

    doSubmit: function()
    {
        if (this.options.onSubmit)
            this.options.onSubmit.call(this, this.terms, this.imagesOnly);
        else if (this.options.onSearch)
            this.options.onSearch.call(this, this.terms, this.imagesOnly);
        IMu.Events.trigger('imu-search', this.terms, this.imagesOnly);
    }
});

/* Source: ./widgets/common/language-selector.js
*/
/*!
 * Simple widget to allow the user to switch languages.
 *
 * @since 2.0
 */
IMu.Widgets.add('language-selector', 'base',
{
	_construct: function()
	{
		this._super.apply(this, arguments);
		this.classes.push('imu-language-selector');

		this.registerOptions
		({
            /*!
             * Specifies that a label (prompt) should be added before any
             * selection elements.
             */
			showLabel: false
		});
	},

	// view methods
    /*!
    ** Get the available language options.
    **
    ** @returns string[]
    **   An array of ``string``\s representing the available languages.
    */
	getLanguages: function()
	{
		var list = [];
		for (var code in IMu.Languages.registered)
		{
			var lang = IMu.Languages.registered[code];
			var item =
			{
				code: code,
				name: lang.name,
				current: lang == IMu.Languages.current
			};
			list.push(item);
		}
		return list;
	},

	// view events
	languageSelected: function(code)
	{
		IMu.Languages.select(code);
	}
});

