/*!
** Allows a user to manage separate collections.
**
** @since 2.0
*/
IMu.Widgets.add('my-collections', 'base',
{
	_construct: function()
	{
		this._super.apply(this, arguments);
		this.classes.push('imu-my-collections');

		this.registerOptions
		({
            /*!
            ** Specifies whether an export button should be displayed.
            */
			showExport: false,

            /*!
            ** Specifies whether an image export button should be displayed.
            */
			showImageExport: false,

            /*!
            ** Specifies whether a label should be displayed.
            */
			showLabel: false,

            /*!
            ** The user has selected a different group.
            */
			onChangeGroup: undefined,

            /*!
            ** The user has requested the current group is to be exported.
            */
            onExportGroup: undefined,

            /*!
            ** The user has requested the images in the current group is 
            ** to be exported.
            */
            onExportImageGroup: undefined,

            /*!
            ** The user has requested that the current group is to be restored.
            **
            ** The ``group`` parameter is a simple JavaScript object which
            ** includes the following elements:
            **
            ** * ``name`` (*string*) The name of the group.
            ** * ``irn`` (*number*) The group's irn in the webgroups table.
            ** * ``entries`` (*array*) The set of records in the group.
            **       
            ** Each element in the ``entries`` array is a simple
            ** JavaScript object.
            **
            ** @param group object
            **   The group to be restored.
            */
			onRestoreGroup: undefined
		});
	},

	// public

	// view methods
    /*!
    ** Creates a new collection group.
    */
	addGroup: function()
	{
		IMu.User.addGroup();
	},

    /*!
    ** Exports columns in a collection group.
    */
	exportGroup: function()
	{
		if (this.options.onExportGroup)
			this.options.onExportGroup.call(this, IMu.User.group);
	},

    /*!
    ** Exports images in a collection group.
    */
    exportImageGroup: function()
    {
        if (this.options.onExportImageGroup)
            this.options.onExportImageGroup.call(this, IMu.User.group);
    },

    /*!
    ** Switch to the next collection group.
    */
	nextGroup: function()
	{
		IMu.User.nextGroup();
	},

    /*!
    ** Switch to the previous collection group.
    */
	previousGroup: function()
	{
		IMu.User.previousGroup();
	},

    /*!
    ** Removes a collection group.
    */
	removeGroup: function()
	{
		IMu.User.removeGroup();
	},

    /*!
    ** Changes the name of a collection group.
    */
	renameGroup: function(name)
	{
		if (name != IMu.User.group.name)
			IMu.User.renameGroup(name);
	},

    /*!
    ** Restores a collection group.
    */
	restoreGroup: function()
	{
		if (this.options.onRestoreGroup)
			this.options.onRestoreGroup.call(this, IMu.User.group);
	}

	// protected
});

/* Source: ./widgets/common/paged-display.js
*/
/*!
** @since 2.0
*/
IMu.Widgets.add('paged-display', 'base',
{
	_construct: function()
	{
		this._super.apply(this, arguments);
		this.classes.push('imu-paged-display');

		this.registerOptions
		({
			showHeader: false,

            onSelected: undefined
		});

		this.pages = [];
		this.selected = -1;
	},

	/*!
    ** Adds a widget to the set to be displayed.
    */
	addWidget: function(name, options)
	{
        var page = {};
        this.pages.push(page);
        if (this.selected < 0)
            this.selected = 0;

        var pageNumber = this.pages.length;
        page.owner = jQuery('<div/>');
        page.owner.addClass('page page-' + pageNumber); 
        page.owner.visible(false);

        page.widget = page.owner.IMu(name, options);
        page.widget.controller = this;
        page.widget.pageNumber = pageNumber;

        /* Override fixedHeight setting to use
        ** the value on the paged-display itself
        */
        page.widget.fixedHeight = this.fixedHeight;

        page.title = name;

        return page;
    },

    /*!
    ** Gets information about a page.
    **
    ** @param index int
    **   The number of the page.
    **
    ** @returns object 
    **   The information about the page.
    */
	get: function(index)
	{
		if (index === undefined)
			index = this.selected;
		if (index < 0)
			return undefined;
		if (index >= this.pages.length)
			return undefined;
		return this.pages[index];
	},

    /*!
    ** Selects a page.
    **
    ** @param index int
    **   The number of the page.
    **
    ** @returns boolean
    **   A flag indicating whether a new page was selected.
    */
	select: function(index)
	{
		if (index < 0)
			return false;
		if (index >= this.pages.length)
			return false;
		if (index == this.selected)
			return false;
		if (! this.view.select(index))
            return false;
        this.selected = index;
        if (this.options.onSelected)
            this.options.onSelected.call(this, this.selected);
        return true;
	},

    /*!
    ** Depricated.
    ** Adds a widget to the set to be displayed.
    */
    add: function(name, options)
    {
        return this.addWidget(name, options);
    }
});

/* Source: ./widgets/common/record-browser.js
*/
/*!
 * Displays an EMu record.
 *
 * @since 2.0
*/
(function()
{
    IMu.Widgets.add('record-browser', 'base',
    {
        _construct: function()
        {
            var self = this;

            self._super.apply(self, arguments);
            self.classes.push('imu-record-details');
            this.classes.push('imu-record-browser');

            self.registerOptions
            ({
                /*!
                ** If **true** will load the default record when the view is
                ** shown.
                ** Value is set to **true** by default for legacy purposes.
                */
                loadOnShowView: true,

                /*!
                ** If **true** includes a control to allow the record to be selected.
                ** When selected the record is added to the user's current
                ** collection.
                */
                showSelectionControl: IMu.Config.showSelectionControls,

                onRecordToggled: undefined
            });

            self.module = undefined;
            self.key = undefined;
        },

        _ready: function()
        {
            var self = this;

            self.getMaster();
            self.getFromURL();
            if (self.options.useURL)
            {
                IMu.Events.bind('hash-loaded', function()
                {
                    self.getMaster();
                    self.getFromURL();
                    self.load();
                });
            }
        },

        /*!
        ** Displays the record registered as the master.
        */
        showMaster: function()
        {
            var self = this;

            self.getMaster();
            self.load(true);
        },

        /*!
        ** Display a specific record.
        **
        ** @param module string
        **   The name of the module containing the record to be
        **   displayed.
        **
        ** @param key integer
        **   The IRN of the record to be displayed.
        */
        showRecord: function(module, key)
        {
            var self = this;

            if (key != undefined)
            {
                self.module = module;
                self.key = key;
            }
            else
            {
                var a = module.split(/[.:]/);
                if (a.length < 2)
                    return;
                self.module = a[0];
                self.key = a[1];
            }
            self.load(true);
        },

        // view methods
        recordToggled: function(rid, on)
        {
            var self = this;

            IMu.log('recordToggled: {0} {1}', rid, (on ? 'on' : 'off'));
            var parts = rid.split(':');
            IMu.User.load(function()
            {
                if (on)
                    IMu.User.addEntry(parts[0], parts[1]);
                else
                    IMu.User.removeEntry(parts[0], parts[1]);

                if (self.options.onRecordToggled)
                    self.options.onRecordToggled.call(self, rid, on);
            });
        },

        // protected
        showView: function()
        {
            if (this.options.loadOnShowView)
                this.load(true);
        },

        // private
        getFromURL: function()
        {
            var self = this;

            if (! self.options.useURL)
                return false;
            return self.splitKey(IMu.URL.Hash.get('rid'));
        },

        getMaster: function()
        {
            var self = this;

            return self.splitKey(IMu.Config.browseMaster);
        },

        load: function(updateURL)
        {
            var self = this;

            if (! self.view)
                return;
            if (! self.module || ! self.key)
                return;

            var key = self.module + '.' + self.key;

            self.destroySearch();
            request = new IMu.Request.Search();
            request.findKey(key, function(data)
            {
                request.fetch('start', 0, 1, 'browse', function(result, success)
                {
                    if (! success || ! result)
                        return;

                    var data = result;
                    if (! data)
                        return;

                    if (! data.modules)
                        return;
                    if (data.modules.length < 1)
                        return;
                    if (! data.modules[0].rows)
                        return;
                    if (data.modules[0].rows.length < 0)
                        return;

                    var module = data.modules[0].name;
                    var method = 'show_' + module;
                    if (! (method in self.view))
                        method = 'show_default';

                    var row = data.modules[0].rows[0];

                    row.source = module;

                    /* Tranform older form of rid (module:irn) to
                    ** newer form (module.irn)
                    */
                    row.rid = row.rid.replace(':', '.');

                    self.view[method](row);

                    if (self.options.useURL && updateURL)
                        IMu.URL.Hash.set('rid', row.rid);

                    IMu.Events.trigger('record-browser-load', row.rid);
                });
            });
        },

        destroySearch: function()
        {
            if (request != undefined)
                request.onComplete = undefined;
        },

        splitKey: function(rid)
        {
            var self = this;

            if (! rid)
                return false;
            var matches = rid.match(/^([^.:]+)[.:](\d+)$/);
            if (! matches)
                return false;
            self.module = matches[1];
            self.key = matches[2];
            return true;
        }

    });

    // Private
    var request = undefined;
})();

/* Source: ./widgets/common/search-form.js
*/
/*!
** A widget for searching.
**
** @since 2.0
*/
IMu.Widgets.add('search-form', 'base',
{
	_construct: function()
	{
		this._super.apply(this, arguments);
		this.classes.push('imu-search-form');

		this.registerOptions
		({
            /*!
            ** Text to display as a tooltip when hovered
            */
            hover: undefined,

           /*!
            ** Specifies if a clear button should be added.
            **
            ** @type boolean
            */
            showClear: false,

            /*!
            ** Specifies if a search button should be added.
            **
            ** @type boolean
            */
			showSubmit: true,

			/*!
            ** Specifies that an "Only items with images" prompt
            ** should also be shown.
            **
            ** @type boolean
            */
            onlyItemsWithImages: true,

            /*!
            ** The user has pressed the clear button.
            */
            onClear: undefined,

            /*!
            ** The user has pressed the search button.
            */
            onSearch: undefined,

            buttonClass: undefined,
            promptClass: undefined,
            inputClass: undefined
		});
		
		this.imagesOnly = false;

		this.fields = [];
	},

	// Public methods
    /*!
    ** Adds fields to the search form.
    */
	add: function()
	{
		for (var i = 0; i < arguments.length; i++)
		{
			var fields = arguments[i];
			if (IMu.Type.get(fields) == 'object')
				fields = [fields];
			for (var j = 0; j < fields.length; j++)
			{
				var field = fields[j];
				this.fields.push(field);
			}
		}
	},

	/*!
	** Clears the search form.
	*/
	clear: function()
	{
		if (this.view)
			this.view.clear();
	},

    /*!
    ** Gets the search terms from each of the fields.
    */
	getTerms: function()
	{
		var terms = new IMu.Terms();
		for (var i = 0; i < this.fields.length; i++)
		{
			var field = this.fields[i];

			if (! field.column)
				continue;
			if (! (field.input || field.control))
				continue;
			var value;
            if (field.input)
                value = field.input.val();
            else if (field.control)
                value = field.control.getValue();
			if (value == '')
				continue;

            if (field.type == 'selection')
			    terms.add(field.column, value, '=');
            else
			    terms.add(field.column, value);
		}
		return terms;
		
	},

	// view methods
    doClear: function()
    {
        this.clear();
        if (this.options.onClear)
            this.options.onClear.call(this);
        IMu.Events.trigger('imu-clear');
    },

    /*!
    ** Initialises a search.
    */
	search: function()
	{
		var terms = this.getTerms();
		IMu.log('terms {0}', terms);
		if (this.options.onSearch)
			this.options.onSearch.call(this, terms,this.imagesOnly);
		IMu.Events.trigger('imu-search', terms,this.imagesOnly);
	}
});

