/* Source: ./widgets/common/control.js
*/
/*!
 ** Base widget for specific controls.
 **
 ** @since 2.0
 */
IMu.Widgets.add('control', 'base',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-control');

        this.registerOptions
        ({
            /*!
            ** Text to be displayed as a hint for data input.
            **
            ** How this is used depends on the type of control. For example,
            ** for a text box the hint is shown both as a title (hover-over)
            ** and in the text box itself.
            */
            hint: undefined,

            /*!
            ** The icons used to complement the `control` widget.
            **
            ** In general these are used for control validation, though they
            ** can also be used for other purposes.
            */
            icons:
            {
                /*!
                ** The initial icon to be displayed by the `control` when it
                ** is first created.
                */
                inital: undefined,

                /* The next three are associated with validation.
                */
                /*!
                ** The icon to be displayed when validation succeeds.
                */
                ok: undefined,

                /*!
                ** The icon to be displayed if a `control` is left empty yet has
                ** a ``requirement`` of ``suggested``.
                */
                empty: 'lightbulb',

                /*!
                ** The icon to be displayed if validation fails.
                */
                invalid: 'exclam',

                /* Used to indicate a delay.
                **
                ** There is no current functionality to support this.
                */
                spinner: undefined

                /* Others can be added and then set using setIcon().
                */
            },

            /*!
            ** If **true**, display the control as read-only.
            */
            readonly: false,

            /*!
            ** Used to determine how a control should be styled
            ** Two possible options : **mandatory** or **suggested**.
            */
            requirement: undefined,

            /*!
            ** Used to set the tabindex attribute on the control.
            */
            tabIndex: undefined,


            /*!
            ** Called when the value of the control has changed.
            */
            onChange: undefined,

            onClickIcon: undefined,

            /*!
            ** Called when control has received keyboard focus.
            */
            onGainFocus: undefined,

            /*!
            ** Called when the control has lost keyboard focus.
            */
            onLoseFocus: undefined,

            /*!
            ** Called as a part of the **validate( )** function chain.
            ** This occurs after a `control`'s  built-in validation and 
            ** gives a `control` instance the chance to review the validation.
            */
            onValidate: undefined,

            /*
            ** Called after standard validation has taken place.
            ** This give an individual control the chance to review the
            ** validation.
            */
            //onValidated: undefined
            
            /*!
            ** If **true**, causes the **validate( )** function to be called 
            ** when the `control`'s value changes.
            */
            validateOnChange: false,

            /*!
            ** If **true**, causes the **validate( )** function to be called
            ** when the `control` gains focus.
            */
            validateOnGainFocus: false,

            /*!
            ** If **true**, causes the **validate( )** function to be called
            ** when the `control` loses focus.
            */
            validateOnLoseFocus: false
        });

        this.value = undefined;
    },

    /*!
    ** Compares the value of this control against another control.
    ** 
    ** @returns 0
    **   By default, all controls are equal.
    */
    compare: function()
    {
        return 0;
    },

    /*!
    ** Gets a normalized version of the value that can be evaluated as either
    ** <, == or > than another normalized value of the same control.
    **
    ** By default, simply return the value.
    */
    getSortableValue: function()
    {
        return this.getValue();
    },

    getAsyncValue: function(callback)
    {
        if (! callback)
            return;

        var value = this.getValue();
        callback(value);
    },

    /*!
    ** Gets the current value of the control.
    **
    ** @returns mixed
    **   The control's current value.
    */
    getValue: function()
    {
        if (this.view)
            this.value = this.view.getValue();
        if (this.value === undefined)
            this.value = null;
        return this.value;
    },

    /*!
    ** Sets the image that is to be displayed in the control and its tooltip.
    **
    ** @param name
    **   The name of the icon to be used.
    **   If this value is not defined in icons, no image will be displayed.
    **
    ** @param info
    **   The message to be displayed as a tooltip.
    **   Clicking on the image will also bring up a dialogue box displaying the
    **   message.
    */
    setIcon: function(name, info)
    {
        this.view.setIcon(name, info);
    },

    /*!
    ** Sets the value of the control.
    **
    ** @param mixed
    **   The value to assign.
    */
    setValue: function(value, callback)
    {
        var self = this;

        self.value = value;
        if (self.view)
        {
            self.view.setValue(self.value);
            self.validateValue(self.value, function(info)
            {
                if (callback)
                    callback.call(self, info);
            });
        }
    },

    /*!
    ** Control level validation.
    **
    ** Creates an ``info`` object containing ``state`` and ``details`` of the 
    ** `control`.
    ** ``state` defaults to **ok** and ``details``defaults to ``undefined``.
    ** 
    ** A two step validation process then occurs:
    ** 1) Built-in rules that always apply to the `control` widget are checked
    ** 2) Custom rules set at instantiation are run
    ** 
    ** Once the validation process has concluded, the `control` displays the
    ** results and then fires a callback event, if one exists.
    **
    ** Each subsequent function in the validation chain occurs as a callback
    ** of the previous function to guard against potential unexpected
    ** asynchronous events.
    **
    ** @param callback function
    **   The function to be called at the end of the validation chain.
    **   Takes ``info`` as an argument.
    */
    validate: function(callback)
    {
        var self = this;

        var info =
        {
            state: 'ok',
            details: undefined
        };

        var value = self.getValue();
        self.doBuiltinValidation(info, value, function()
        {
            self.doCustomValidation(info, value, function()
            {
                self.showValidationState(info, function()
                {
                    if (callback)
                        callback.call(self, info);
                });
            });
        });
    },
    // end interface

    /*!
    ** Control level built-in validation.
    ** Called via the **validate( )** function.
    **
    ** A set of rules which always apply to the `control` widget are checked and
    ** the results are stored in ``info``.
    **
    ** For the `control` widget, the only rule we can check is that there a
    ** value exists when a ``requirement`` has been set.
    ** 
    ** If input is **mandatory** and no value is given, the `control` is
    ** essentially invalid.
    ** If input is **suggested** and no value is given, the user may need to be
    ** notified before proceeding.
    ** In both cases ``info.details`` is set to hash key from the strings file.
    **
    ** @param info
    **   Information about the current state of the `control`.
    **   At this point ``info.state`` should be **ok** and ``info.details`` 
    **   should be ``undefined.
    **
    ** @param value
    **   The current value of the widget.
    **
    ** @param callback function
    **   Returns control back to the previous function once validation has
    **   concluded.
    */
    doBuiltinValidation: function(info, value, callback)
    {
        if (this.isEmpty(value))
        {
            var requirement = this.options.requirement;
            if (requirement == 'mandatory')
            {
                info.state = 'invalid';
                info.details = 'validation-empty-mandatory';
            }
            else if (requirement == 'suggested')
            {
                info.state = 'empty';
                info.details = 'validation-empty-suggested';
            }
        }
        callback();
    },

    /*
    ** Called by the view when the control's value has changed.
    */
    doChange: function()
    {
        this.value = this.view.getValue();
        if (this.options.onChange)
            this.options.onChange.call(this, this.value);
        else if (this.options.validateOnChange)
            this.validate();
    },

    /*! 
    ** Control level custom validation.
    ** Called via the **validate( )** function.
    **
    ** Checks to see if there is an ``onValidate`` function in the options.
    ** If one exists, it is called before control is passed back to 
    ** **validate( )**.
    **
    ** @param info
    **   Information about the current state of the `control` before any
    **   custom validation.
    **
    ** @param value
    **   The current value of the widget.
    **
    ** @param callback function
    **   Returns control back to the previous function once validation has
    **   concluded.
    */
    doCustomValidation: function(info, value, callback)
    {
        var self = this;

        if (! self.options.onValidate)
        {
            callback();
            return;
        }
        self.options.onValidate.call(self, info, value, function()
        {
            callback();
        });
    },

    /*
    ** Called by the view when the control has gained focus.
    */
    doGainFocus: function()
    {
        if (this.options.onGainFocus)
            this.options.onGainFocus.call(this);
        else if (this.options.validateOnGainFocus)
            this.validate();
    },

    /*
    ** Called by the view when the control has lost focus.
    */
    doLoseFocus: function()
    {
        if (this.options.onLoseFocus)
            this.options.onLoseFocus.call(this);
        else if (this.options.validateOnLoseFocus)
            this.validate();
    },

    getIconURL: function(value)
    {
        // TODO: what about those placeholders?
        if (! IMu.Type.isObject(this.options.icons))
            return undefined;

        var icon = this.options.icons[value];
        if (! icon)
            return undefined;

        return IMu.Request.getURL('Image') + '&name=' + icon;
    },

    /*
    ** Creates a normalised version of list-related options.
    **
    ** Convenience method used to normalise list-related options:
    **
    ** * list option of selection-control
    ** * suggest option of text-control
    **
    ** The method makes some guesses as to the type of list being
    ** specified.
    **
    ** @param data
    **   The option as specified by the user.
    **
    ** @returns object
    **   The option normalised into a standard stucture.
    */
    getListInfo: function(data)
    {
        var info = {};
        switch (IMu.Type.get(data))
        {
            case 'array':
                info.type = 'array';
                info.values = data;
                break;

            case 'function':
                info.type = 'function';
                info.code = data;
                break;

            case 'object':
                for (var name in data)
                    info[name] = data[name];
                break;

            case 'string':
                // TODO this should be more flexible
                info.type = 'lookup';
                info.name = data;
                break;
        }
        if (! info.type)
            info.type = 'empty';
        return info;
    },

    isEmpty: function(value)
    {
        if (value === undefined)
            value = this.getValue();
        return (value === undefined || value === '' || value === null);
    },

    optionsChanged: function(list)
    {
        var view = this.view;
        if (! view)
            return;

        for (var i in list)
        {
            var item = list[i];
            if (item.name == 'readonly')
                view.setReadOnly();
            else if (item.name == 'requirement')
                view.setRequirement();
            else if (item.name == 'tabIndex')
                view.setTabIndex();
        }
    },

    /*!
    ** Control level show validation state.
    **
    ** By default do nothing.
    **
    ** @param info
    **   Information about the current state of the `control` after validation.
    **   This parameter is taken for consistency.
    **
    ** @param callback function
    **   Returns control back to the previous function.
    */
    showValidationState: function(info, callback)
    {
        callback();
    },

    /* This function is pretty much identical to ``validate`` except
    ** it is used when the caller wants to explicitly define what the
    ** value being validated is.
    ** 
    ** This should be for strictly PRIVATE use only.
    ** Appropriate use would be in the setValue function, where the view
    ** part of the control might not be able to properly represent the data.
    ** For example, a control that has specific values that can be set but 
    ** the set of values have not been populated at the time of settng the
    ** widget value.
    */
    validateValue: function(value, callback)
    {
        var self = this;

        var info =
        {
            state: 'ok',
            details: undefined
        };

        self.doBuiltinValidation(info, value, function()
        {
            self.doCustomValidation(info, value, function()
            {
                self.showValidationState(info, function()
                {
                    if (callback)
                        callback.call(self, info);
                });
            });
        });
    }
});

/* Source: ./widgets/common/box-control.js
*/
IMu.Widgets.add('box-control', 'control',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-box-control');

        this.registerOptions
        ({
            /*!
            ** If **true**, causes the **validate( )** function to be called 
            ** when the user presses the ``Enter`` key.
            */
            validateOnEnter: false,

            /*!
            ** Called when the user has pressed the ``Enter`` key.
            */
            onEnter: undefined
        });
    },
    // end interface

    doEnter: function()
    {
        if (this.options.onEnter)
            this.options.onEnter.call(this);
        else if (this.options.validateOnEnter)
            this.validate();
    },
       
    /*!
    ** Box-control level show validation.
    ** Called via the **validate( )** function.
    ** Uses information from validation to set an appropriate icon and tooltip.
    **
    ** @param info
    **   Information about the current state of the `box-control` after validation.
    **   ``info.state`` is used to set the type of validation icon to be
    **   displayed while ``info.details`` is used to set the tooltip and popup
    **   dialogue text.
    **
    ** @param callback function
    **   Returns control back to the previous function once icons have been set.
    */
    showValidationState: function(info, callback)
    {
        this.setIcon(info.state, info.details);
        callback();
    }
});

/* Source: ./widgets/common/checkbox-control.js
*/
/*!
** Simple checkbox control.
**
** @since 2.0
*/
IMu.Widgets.add('checkbox-control', 'control',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-checkbox-control');

        this.value = false;
    },

    /*!
    ** Compares the value of this control against another `checkbox-control`.
    **
    ** @returns result
    **   A value indicating the relationship between the checkboxes.
    **   * < 0 - this control is unchecked but the other control is.
    **   * = 0 - both controls are either checked or unchecked.
    **   * > 0 - this control is checked but the other control is not.
    **   * undefined - the values cannot be compared.
    */
    compare: function(otherControl)
    {
        var otherValue = otherControl.widget.value;
        if (this.value == otherValue)
            return 0;
        else if (this.value)
            return 1
        else
            return -1;
    }
});

/* Source: ./widgets/common/date-control.js
*/
/*!
** Simple date control.
**
** @since 2.0
*/
IMu.Widgets.add('date-control', 'box-control',
{
    _construct: function()
    {
        var self = this;
        self._super.apply(self, arguments);
        self.classes.push('imu-date-control');

        self.registerOptions
        ({
            /*!
            ** The date format to be used.
            **
            ** The formatting of dates is problematic and is tied up
            ** with a much larger issue of localisation.
            **
            ** This option only provides a short-cut workaround.  As such,
            ** it may be deprecated in the future!
            */
            format: 'dd/mm/yy',

            /*!
            ** The locale to match date patterns against.
            ** If **undefined**, will attempt to guess based on the user's
            ** current location.
            **
            ** For supported locales see globalize/cultures in the dist
            ** directory.
            */
            language: undefined,

            /*!
            ** The list of date patterns to match against.
            **
            ** By default all but pure time based patterns have been included.
            ** For reasons of locale dependent variation, the exact pattern
            ** formats cannot be listed in the documentation.
            **
            ** For supported patterns see globalize/cultures in the dist
            ** directory.
            */
            patterns:
            [
                'd',
                'D',
                'M',
                'Y',
                'S'
            ],

            /*!
            ** If true, display a pop-up date-picker when the control
            ** gets focus.
            */
            picker: false
        });

        self.currentPattern = undefined;
        self.language = undefined;
        IMu.Events.bind('language-changed', function()
        {
            self.changeLanguage();
        });
    },

    _ready: function()
    {
        if (this.options.language)
            this.language = this.options.language;
        else
            this.language = IMu.Languages.current.code;
    },

    /*!
    ** Date-control level built-in validation.
    ** Called via the **validate( )** function.
    **
    ** A set of rules which always apply to the `date-control` widget are 
    ** checked and the results are stored in ``info``.
    **
    ** If the results of the parent **doBuiltinValidation( )** call are **ok**
    ** and the value is not ``undefined``, the value will be checked to see if
    ** it is a valid date.
    **
    ** If the value is not a valid date, ``info.state`` will be set to
    ** **invalid** and ``info.details`` will be set to a meaningful string to
    ** reflect why the value is invalid.
    **
    ** Currently this is a work in progress and there are no rules in place.
    **
    ** @param info
    **   Information about the current state of the `date-control`.
    **   Further validation is only required if ``info.state`` is **ok**.
    **
    ** @param value
    **   The current value of the widget.
    **
    ** @param callback function
    **   Returns control back to the previous function once validation has
    **   concluded.
    */
    doBuiltinValidation: function(info, value, callback)
    {
        var self = this;

        self._super(info, value, function()
        {
            if (info.state == 'ok' && value != null)
            {
                if (self.getSortableValue() == null)
                {
                    info.state = 'invalid';
                    info.details = 'validation-invalid-date-format';
                }
            }
            callback(info, value);
        });
    },

    /* Prevent overwriting of value by parent control.
    ** This is handy for if getSortableValue has set a more meaningful value.
    */
    getValue: function()
    {
        if (this.value)
            return this.value;
        return this._super();
    },

    getSortableValue: function()
    {
        if (! this.value)
            return null;

        if (this.value instanceof Date)
            return this.value;

        var language = this.language;
        if (! language)
            language = Globalize.culture().name;
        
        var parsedDate = null;
        for (var i in this.options.patterns)
        {
            var pattern = this.options.patterns[i];
            parsedDate = Globalize.parseDate(this.value,
                Globalize.culture(language).calendar.patterns[pattern]);
            if (parsedDate != null)
            {
                this.currentPattern = this.options.patterns[i];
                return this.value = parsedDate;
            }
        }
        return undefined;
    },

    setValue: function(value, callback)
    {
        var language = this.language;
        this.language = "en";

        this._super(value, callback);
        this.changeLanguage(language);
    },
    // end interface
   
    /* It should be noted that if an invalid date becomes valid after a
    ** language change, the implied value changes
    */
    changeLanguage: function(newLanguage)
    {
        if (! newLanguage)
            newLanguage = IMu.Languages.current.code;

        if (! this.value)
        {
            this.language = newLanguage;
            return;
        }
        var sortableValue = this.getSortableValue();
        if (! sortableValue)
        {
            this.language = newLanguage;
            return;
        }
        var formattedValue = Globalize.format(
            sortableValue, 
            this.currentPattern,
            IMu.Languages.current.code);
        
        // change language before setting value, otherwise validation error
        this.language = newLanguage;
        if (formattedValue)
            this.view.setValue(formattedValue);
    }
});

/* Source: ./widgets/common/icon-control.js
*/
/*!
** Control to show a logical value as an icon.
**
** @since 2.0
*/
IMu.Widgets.add('icon-control', 'control',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-icon-control');

        this.registerOptions
        ({
        });
    },

    // convenience function
    getURL: function(value)
    {
        return this.getIconURL(value);
    },

    // While this seems strange, sorting on columns with hazard icons has been
    // requested by clients.
    /*!
    ** Compares the value of this control against another `icon-control`. 
    ** Uses the `icon`'s name as a value.
    **
    ** @returns result
    **   A value indicating the relationship between icons.
    */
    compare: function(otherControl)
    {
        var value = undefined;
        if (IMu.Type.isNumber(this.value))
            value = "'" + this.value + "'";
        else
            value = this.value;
            
        var otherValue = otherControl.widget.value;
        if (IMu.Type.isNumber(otherValue))
            otherValue = "'" + otherValue + "'";

        if (value == otherValue)
            return 0;
        else if (value == '' || otherValue == '')
            return undefined;
        else if (value < otherValue)
            return -1;
        else if (value > otherValue)
            return 1;
    }
});

/* Source: ./widgets/common/integer-control.js
*/
/*!
** Integer input control.
**
** @since 2.0
*/
IMu.Widgets.add('integer-control', 'box-control',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-integer-control');

        this.registerOptions
        ({
        });

        this.regex = undefined;
    },

    getSortableValue: function()
    {
        if (! this.value)
            return null;

        if (! this.regex)
            this.regex = /^\s*(\-|\+)?\d+\s*$/;
                
        if (! this.regex.test(this.value))
            return undefined;
        return parseInt(this.value, 10);
    },

    /*!
    ** Integer-control level built-in validation.
    ** Called via the **validate( )** function.
    **
    ** A set of rules which always apply to the `integer-control` are checked
    ** and the results are stored in ``info``.
    **
    ** The `integer-control` runs its value against a regex to ensure it
    ** matches the correct character pattern for an integer.
    **
    ** @param info
    **   Information about the current state of the `integer-control`.
    **
    ** @param value
    **   The current value of the widget.
    **
    ** @param callback function
    **   Returns control back to the previous function once validation has 
    **   concluded.
    */
    doBuiltinValidation: function(info, value, callback)
    {
        var self = this;

        // Don't want all the extra base stuff that parseInt() does.
        if (! self.regex)
            self.regex = /^\s*(\-|\+)?\d+\s*$/;

        self._super(info, value, function()
        {
            if (info.state == 'ok' && value != null)
            {
                if (! self.regex.test(value))
                {
                    info.state = 'invalid';
                    info.details = 'validation-invalid-integer';
                }
            }
            callback();
        });
    }
});

/* Source: ./widgets/common/number-control.js
*/
/*!
** Number input control.
**
** @since 2.0
*/
IMu.Widgets.add('number-control', 'box-control',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-number-control');

        this.registerOptions
        ({
        });
    },

    getSortableValue: function()
    {
        if (! this.value)
            return null;

        if (! this.regex)
            this.regex = /^\s*(\-|\+)?\d+(\.\d+)?\s*$/;
        
        if (! this.regex.test(this.value))
            return undefined;
        return parseFloat(this.value);
    },

    /*!
    ** Number-control level built-in validation.
    ** Called via the **validate( )** function.
    **
    ** A set of rules which always apply to the `number-control` are checked
    ** and the results are stored in ``info``.
    **
    ** The `number-control` runs its value against a regex to ensure it
    ** matchest the correct character pattern for a number.
    **
    ** @param info
    **   Information about the current state of the `number-control`.
    **
    ** @param value
    **   The current value of the widget.
    **
    ** @param callback function
    **   Returns control back to the previous function once validation has
    **   concluded.
    */
    doBuiltinValidation: function(info, value, callback)
    {
        var self = this;

        // Don't want all the extra base stuff that parseInt() does.
        if (! self.regex)
            self.regex = /^\s*(\-|\+)?\d+(\.\d+)?\s*$/;

        self._super(info, value, function()
        {
            if (info.state == 'ok' && value != null)
            {
                if (! self.regex.test(value))
                {
                    info.state = 'invalid';
                    info.details = 'validation-invalid-number';
                }
            }
            callback();
        });
    }
});

/* Source: ./widgets/common/selection-control.js
*/
/*!
** Selection (typically a drop-down list) control.
**
** @since 2.0
*/
IMu.Widgets.add('selection-control', 'control',
{
    _construct: function()
    {
        this._super.apply(this, arguments);
        this.classes.push('imu-selection-control');

        this.registerOptions
        ({
            /*!
            ** The source of the selection list to be displayed. 
            ** See the $<setList> method below for more information.
            */
            list: undefined,

            /*!
            ** This indicates whether we need to fetch other languages
            ** when we use autocomplete.
            */
            getAllLanguages: undefined

        });
    },

    createView: function()
    {
        if (! this._super.apply(this, arguments))
            return false;

        if (this.options.list)
            this.setList(this.options.list);

        return true;
    },

    /*!
    ** Set the list of values to be displayed.
    **
    ** The type of the ``data`` argument can be:
    **
    ** * *object*
    **
    **   This is the most flexible type of information. The *object*
    **   can contain the following properties:
    **
    **   * ``type`` (*string*)
    **
    **     The type of list being specified. Can be:
    **
    **     * **array**
    **     * **function**
    **     * **lookup**
    **
    ** * *array*
    ** 
    ** * *function*
    **
    ** * *string*
    */
    setList: function(data)
    {
        var info = this.getListInfo(data);
        switch (info.type)
        {
          case 'array':
            this.setArrayList(info);
            break;

          case 'function':
            this.setFunctionList(info);
            break;

          case 'lookup':
            this.setLookupList(info);
            break;

          default:
            this.setViewList([]);
            break;
        }
    },

    setArrayList: function(info)
    {
        var self = this;

        if (! IMu.Type.isArray(info.values))
        {
            self.setViewList([]);
            return;
        }
        self.setViewList(info.values);
    },

    setFunctionList: function(info)
    {
        var self = this;

        if (! IMu.Type.isFunction(info.code))
        {
            self.setViewList([]);
            return;
        }
        info.code.call(self, info, function(list)
        {
            self.setViewList(list);
        });
    },

    setLookupList: function(info)
    {
        var self = this;

        if (! IMu.Type.isString(info.name))
        {
            self.setViewList([]);
            return;
        }
        var name = info.name;

        var level = info.level;
        if (level === undefined)
            level = 0;

        var keys = undefined;
        if (IMu.Type.isArray(info.keys))
            keys = info.keys;

        var lookup = new IMu.Request.Lookup();
        if (self.options.getAllLanguages &&
            self.options.getAllLanguages == 1)
        {
            lookup.lookupAll(name, level, keys, function(list)
            {
                self.setViewList(list);
            });
        }
        else
        {
            lookup.lookup(name, level, keys, function(list)
            {
                self.setViewList(list);
            });
        }
    },

    setViewList: function(list)
    {
        if (this.view)
            this.view.setList(list);
    },

    /*!
    ** Selection-control level show validation.
    ** Called via the **validate( )** function.
    ** Uses information from validation to set an appropriate icon and tooltip.
    **
    ** @param info
    **   Information about the current state of the `selection-control` after
    **   validation.
    **   ``info.state`` is used to set the type of validation icon to be 
    **   displayed while ``info.details`` is used to set the tooltip and popup
    **   dialogue text.
    **
    ** @param callback function
    **   Returns control back to the previous function once validation has 
    **   concluded.
    */
    showValidationState: function(info, callback)
    {
        this.setIcon(info.state, info.details);
        callback();
    }
});

