(function(theme)
{
    theme.views.register('explore', 'base',
    {
        _source: 'shared/common/explore',

        all:
        {
            _construct: function()
            {
                var self = this;
                self._super.apply(this, arguments);

                self.owner = undefined;

                self.header = undefined;
                self.sidebar = undefined;
                self.content = undefined;
                self.footer = undefined;

                self.toTopButton = undefined;

                // The distance (in pixels) from the end of result set before
                // more records are loaded.
                self.loadDistance = 0;
            },

            _create: function()
            {
                var self = this;
                self._super.apply(this, arguments);

                self.createPage();
                self.loadDistance = $(window).outerHeight() / 2;
            },

            /* A generic view layout
            ** Expected to be overridden in theme/view
            */
            createPage: function()
            {
                var self = this;

                //TODO: this needs to look at widget options to see how to create page
                //eg num columns, sidebar, header

                self.owner = self.widget.owner;
                var options = self.widget.options;

                /* Create sections as per current theme
                */
                if (options.showHeader)
                    self.createHeader();

                if (options.showSidebar)
                    self.createSidebar();

                self.createContent();

                self.createFooter();
            },

            /* Empty by default
            */
            createHeader: function()
            {
            },
            createSidebar: function()
            {
            },
            createContent: function()
            {
                var self = this;

//                self.content = self.widget.owner.child('div', 'content');
                self.content = self.owner.child('div', 'content');
                self.content.css('position', 'relative');

                var table = self.content.child('table');
                table.css('table-layout', 'fixed');

                var tbody = table.child('tbody');
                tbody.css('width', '100%');

                var tr = tbody.child('tr', 'row content');
                self.content = tr;
            },

            createFooter: function()
            {
                var self = this;

                self.footer = self.owner.child('div', 'footer');
                self.footer.css('position', 'relative');

                self.footer.text(IMu.string('loading'));
            },

            setLoadInterval: function(interval)
            {
                var self = this;

                if (! interval)
                    return;
               
                /*
                var owner = jQuery("body > .swipe > .swipe-wrap > .holder");
                if (holder.length != 1)
                    holder = jQuery("body > .holder");
                if (holder.length != 1)
                    return;
                holder = holder[0];

                self.loadInterval = setInterval(function()
                {
                    var scrollHeight = holder.scrollHeight;
                    var scrollTop = holder.scrollTop;

                    var distance = scrollHeight - $(window).height() - scrollTop;
                    if (distance <= self.loadDistance)
                        IMu.Events.trigger('load-records');
                }, interval);
                */
            },
            
            clearLoadInterval: function()
            {
                var self = this;
                clearInterval(self.loadInterval);
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/highlights-banner.js
*/
(function(theme)
{
    theme.views.register('highlights-banner',
    {
        _source: 'shared/common/highlights-banner',

        all:
        {
            _construct: function()
            {
                this._super.apply(this, arguments);

                this.stickyContent = undefined;
                this.dynamicContent = undefined;
                this.slides = [];
                this.currentSlide = null;
            },

            _create: function()
            {
                this._super.apply(this, arguments);

                var holder = jQuery("<div class='holder'></div>");
                
                /* Create elements in order of appearance.
                ** Ordering of elements rather than using css to position is 
                ** important for W3C accessibility.
                */
                var languageDir = undefined;
                if (IMu.Languages.current.dir == 'ltr')
                {
                    languageDir = 'ltr';
                    this.stickyContent = holder.child('div', 'stickyContent');
                    this.dynamicContent = holder.child('div', 'dynamicContent');
                }
                else
                {
                    languageDir = 'rtl';
                    this.dynamicContent = holder.child('div', 'dynamicContent');
                    this.stickyContent = holder.child('div', 'stickyContent');
                }
                
                /* The ltr/rtl css seems buggy.
                ** This is a hack.
                */
                this.widget.owner.removeClass('ltr rtl');
                this.widget.owner.addClass(languageDir);

                if (this.widget.options.loadNarrative)
                    this.beginDelay();

                this.widget.owner.append(holder);
            },

            /* Protected
            */
            addOtherSlide: function(slide, data, module)
            {
                module = module || '';

                var href = undefined;
                if (this.widget.options.linkFormat)
                {
                    /* NOTE: 
                    ** This logic allows for link formats
                    ** that expect the module and/or irn
                    ** or neither.
                    ** Additionally, this logic does not
                    ** protect against scenarios where
                    ** the developer has specified a link
                    ** format that requires this data but
                    ** it is not provided.
                    ** In such cases, the logic elsewhere
                    ** that handles interpreting the URL
                    ** will need to take care of this.
                    */
                    href = IMu.Format.formatParams(
                        this.widget.options.linkFormat,
                        [
                            data.module || '',
                            data.irn || ''
                        ]);
                }
                
                var image;
                var content;
                if (IMu.Languages.current.dir == 'ltr')
                {
                    image = slide.child('a', 'image');
                    content = slide.child('div', 'content');
                }
                else
                {
                    // TODO: the rtl styling for slides needs work.
                    content = slide.child('div', 'content');
                    image = slide.child('a', 'image');
                }

                if (href)
                    image.attr('href', href);


                if (data.image)
                {
                    var url;

                    if (data.image.SupUsage_nesttab &&
                        data.image.SupUsage_nesttab.length)
                    {
                        for (var i = 0; i < data.image.SupUsage_nesttab.length; i++)
                        {
                            var usage = data.image.SupUsage_nesttab[i];
                            var done = false;
                            
                            for (var j = 0; j < usage.length; j++)
                            {
                                if (usage[j] != 'imu-highlights-banner')
                                    continue;

                                var mm = new IMu.Request.Multimedia();
                                mm.setKey(data.image.irn);
                                mm.addFilter('kind', 'supplementary');
                                mm.addFilter('usage', 'imu-highlights-banner');
                                mm.addModifier('format', 'jpeg');
                                url = mm.getURL();

                                done = true;
                                break;
                            }

                            if (done)
                                break;
                        }
                    }
                    else if (data.image.src)
                        url = data.image.src;
                    
                    if (url)
                    {
                        image.child('img',
                        {
                            'src': url
                        });
                    }
                }

                if (data.title)
                    content.child('h3', 'title').text(data.title);

                if (href)
                {
                    var link = content.child('a', 'view-record');
                    var format = IMu.string('highlights-banner-view-module');
                    
                    link.text(IMu.Format.formatParams(format, [module]));

                    link.attr('href', href);
                }

                return slide;
            },

            addSlide: function(data)
            {
                var slide = jQuery('<div class="slide">');
                this.slides.push(slide);
                
                slide.addClass('slide-' + this.slides.length);
                this.hideSlide(this.slides.length - 1);

                if (data.module)
                {
                    var module = data.module.slice(1);
                    module = module.charAt(0).toUpperCase() + module.slice(1);

                    var method = 'add' + module + 'Slide';
                    if (typeof this[method] == 'function')
                        this[method](slide, data);
                    else
                        this.addOtherSlide(slide, data, module);
                }
                else
                    this.addOtherSlide(slide, data, module);

                slide.appendTo(this.dynamicContent);
                return slide;
            },

            beginDelay: function()
            {
                this.widget.owner.addClass('delay');
                this._super.apply(this, arguments);
            },

            endDelay: function()
            {
                this._super.apply(this, arguments);
                this.widget.owner.removeClass('delay');
            },

            hideSlide: function(index)
            {
                this.slides[index].visible(false);
            },

            makeDynamicContent: function(objects)
            {
                this.dynamicContent.empty();
                this.slides = [];
                
                this.setCurrentSlide(null);

                if (! objects.length)
                    return this.dynamicContent;

                for (var i = 0; i < objects.length; i++)
                    this.addSlide(objects[i]);

                this.setCurrentSlide(0);

                this.setupSlideNavigation();

                return this.dynamicContent;
            },

            makeStickyContent: function(title, narrative, attachedRecords)
            {
                var sticky = this.stickyContent;
                sticky.empty();

                if (! title && ! narrative)
                    return sticky;
                
                var holder = sticky.child('div', 'holder');

                if (title)
                    jQuery("<h1>" + title + "</h1>").appendTo(holder);

                if (narrative)
                    jQuery(narrative).appendTo(holder);
                
                var keys = [];
                for (var module in attachedRecords)
                {
                    var records = attachedRecords[module];
                    for (var i = 0; i < records.length; i++)
                        keys.push([module, records[i].irn]);
                }
                if (keys.length)
                {
                    var a = holder.child('a', 
                    {
                        'class': 'view-all',
                        'title': IMu.string('highlights-banner-view-all')
                    });
                    a.text(IMu.string('highlights-banner-view-all'));
                    
                    a.click(function()
                    {
                        var search = new IMu.Request.Search();
                        search.findKeys(keys, function(hits)
                        {
                            IMu.log('restore: hits {0}', hits);
                            IMu.Events.trigger('user-search-complete-success',
                            {
                                'search': search
                            });
                        });
                    });
                }

                return sticky;
            },

            setCurrentSlide: function(index)
            {
                if (this.currentSlide !== null)
                    this.hideSlide(this.currentSlide);
                
                if (index === null || index === undefined)
                    index = null;
                else
                    this.showSlide(index);

                this.currentSlide = index;
            },

            // Implement per theme/client.
            // This is where next/previous buttons are created as well
            // as slideshow timer functionality.
            setupSlideNavigation: function()
            {
            },

            showLoadError: function(errorType)
            {
                var dynamic = this.dynamicContent;
                dynamic.empty();
                
                var error = dynamic.child('div', 'error-message');

                var html = '';
                if (errorType)
                {
                    html = IMu.string('highlights-banner-error-' 
                        + errorType);

                    if (html == 'highlights-banner-error-' + errorType)
                    {
                        html = IMu.string('highlights-banner-unexpected-error');
                        html = IMu.Format.formatParams(html, [errorType]);
                    }

                }
                else
                    html = IMu.string('highlights-banner-error');

                error.html(html); 

                this.endDelay();
            },
            
            showSlide: function(index)
            {
                this.slides[index].visible(true);
                IMu.Events.trigger('highlights-banner-show-slide', 
                    this.slides[index]);
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/control.js
*/
(function(theme)
{
    theme.views.register('control',
    {
        _source: 'shared/common/control',

        all:
        {
            _construct: function()
            {
                this._super.apply(this, arguments);

                this.control = undefined;
                this.tagControl = undefined;
                this.hint = undefined;
                this.holder = undefined;
                this.content = undefined;
                this.icon = undefined;
            },

            _create: function()
            {
                this._super.apply(this, arguments);

                this.holder = this.widget.owner.child('div', 'holder table');
                var row = this.holderRow = this.holder.child('div', 'table-row');

                this.content = row.child('div', 'content table-cell');
                this.icon = row.child('div', 'icon table-cell');
                if (this.widget.options.icons.initial)
                    this.setIcon('initial');

                if (this.widget.options.hint)
                    this.hint = IMu.string(this.widget.options.hint);
            },

            /*!
            ** Called when an icon is clicked.
            **
            ** If a function has been declared in the options, this is called.
            ** If no function exists, a popup dialogue will be created. 
            **
            ** @param message
            **   The message to be shown by the popup dialogue.
            */
            onClickIcon: function(message)
            {
                if (this.widget.options.onClickIcon)
                {
                    this.widget.options.onClickIcon.call(this);
                    return;
                }
                if (! message)
                    return;
                var dialogue = new IMu.App.Dialogue();
                dialogue.setMessage(IMu.string(message));
                dialogue.addButton('dialogue-button-close');
                dialogue.show();
            },

            setup: function()
            {
                var self = this;

                if (self.widget.value !== undefined)
                    self.setValue(self.widget.value);
                self.setReadOnly();
                self.setRequirement();
                self.setTabIndex();
                self.control.on('focus', function()
                {
                    self.widget.doGainFocus();
                });
                self.control.on('blur', function()
                {
                    self.widget.doLoseFocus();
                });
            },

            /*!
            ** Sets the image to be displayed in the control and its tooltip.
            **
            ** @param name
            **   The name of the icon to be used.
            **   If this value is not defined in icons, no image will be
            **   displayed.
            **
            ** @param info
            **   The message to be displayed as a tooltip.
            **   Clicking on the image will also bring up a dialogue box
            **   displaying the message.
            */
            setIcon: function(name, message)
            {
                var self = this;
                if (! message)
                    message = '';
                var img = self.icon.children('img').first();
                var url = self.widget.getIconURL(name);
                if (! url)
                {
                    if (img)
                        img.remove();
                }
                else
                {
                    if (img.length == 0)
                        img = self.icon.child('img', 'table-cell');
                    img.attr('src', url);
                    img.attr('title', IMu.string(message));

                    jQuery(img).unbind().click(function()
                    {
                        self.onClickIcon(message)
                    });
                }
            },

            setReadOnly: function()
            {
                var disabled = false;
                if (this.widget.options.readonly)
                    disabled = true;
                this.control.attr('disabled', disabled);
            },

            setRequirement: function()
            {
                if (this.widget.options.requirement == "mandatory")
                    this.control.addClass('mandatory');
                if (this.widget.options.requirement == "suggested")
                    this.control.addClass('suggested');
            },

            setTabIndex: function()
            {
                var tabIndex = undefined;
                if (this.widget.options.tabIndex)
                    tabIndex = this.widget.options.tabIndex;
                if (tabIndex)
                    this.control.attr('tabindex', tabIndex);
                else
                    this.control.removeAttr('tabindex');
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/checkbox-control.js
*/
(function(theme)
{
    theme.views.register('checkbox-control', 'control',
    {
        _source: 'shared/common/checkbox-control',

        all:
        {
            _create: function()
            {
                this._super.apply(this, arguments);

                var self = this;

                var widget = self.widget;

                self.control = self.content.child('input type="checkbox"', 'input');
                self.setup();

                if (self.hint)
                    self.control.attr('title', self.hint);

                if (widget.options.onChange)
                {
                    self.control.bind('change', function(e)
                    {
                        widget.options.onChange.call(widget, self.getValue());
                    });
                }
            },

            /*!
            ** Gets the value from the control.
            **
            ** @returns
            **   Returns **true** if checkbox is selected, **false** otherwise.
            */
            getValue: function()
            {
                return this.control.prop('checked');
            },

            /*!
            ** Sets the value of the control.
            **
            ** @param value
            **   A boolean value.
            */
            setValue: function(value)
            {
                this.control.prop('checked', value);
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/box-control.js
*/
(function(theme)
{
    theme.views.register('box-control', 'control',
    {
        _source: 'shared/common/box-control',

        all:
        {
            _create: function()
            {
                this._super.apply(this, arguments);

                var self = this;

                var options = self.widget.options;
                if (options.lines && options.lines > 1)
                {
                    self.control = this.content.child('textarea');
                    self.control.attr('rows', options.lines)
                    self.control.on('input propertychange', function()
                    {
                        self.widget.doChange();
                    });
                }
                else
                {
                    self.control = self.content.child('input type="text"');
                    self.control.on('textchange', function()
                    {
                        self.widget.doChange();
                    });
                }
                self.setup();

                self.contentHint = '';
                if (self.hint)
                {
                    self.control.attr('title', self.hint);
                    self.contentHint = '(' + self.hint + ')';
                    self.control.on('focus', function()
                    {
                        if (self.control.val() == self.contentHint)
                        {
                            self.control.val('');
                            self.control.removeClass('hint');
                        }
                    });
                    self.control.on('blur', function()
                    {
                        if (self.control.val() == '')
                        {
                            self.control.val(self.contentHint);
                            self.control.addClass('hint');
                        }
                    });
                    self.control.blur();
                }
                self.control.on('keypress', function(e)
                {
                    if (e.keyCode == 13)
                        self.widget.doEnter();
                });
                self.control.on('barcode-scanned', function(e, info)
                {
                    self.setValue(info.value);
                    self.widget.doChange();
                });
            },

            /*!
            ** Gets the current value from the control.
            **
            ** @returns value
            **   The current value of the control.
            */
            getValue: function()
            {
                var value = this.control.val();
                if (value == this.contentHint)
                    value = undefined;
                return value;
            },
            
            /*!
            ** Sets a value of the control.
            **
            ** @param value
            **   The value to set.
            */
            setValue: function(value)
            {
                this.control.val(value);
                if (this.contentHint)
                {
                    if (this.control.val() != '')
                        this.control.removeClass('hint');
                    else
                    {
                        this.control.val(this.contentHint);
                        this.control.addClass('hint');
                    }
                }
            }
        }
    });
})(IMu.Themes.shared);

