/* Source: ./shared/common/views/tag-control.js
*/
(function(theme)
{
    theme.views.register('tag-control', 'text-control',
    {
        _source: 'shared/common/tag-control',

        all:
        {
            _create: function()
            {
                this._super.apply(this, arguments);

                var self = this;

                /* make the tags typed display above the input */
                var inputHolder = self.holder.find('.content');
                self.tagHolder = jQuery(
                    '<div class="tag-holder"><div class="tags"/></div>'
                );
                self.tagHolder.prependTo(inputHolder);

                self.submit = undefined;
                if (self.widget.options.readonly)
                {
                    inputHolder.find('input').hide();
                }
                else
                {
                    inputHolder.find('input').attr({'id': 'tag-update-input' });

                    /* add a submit button as a sibling of the text control */
                    self.submit = inputHolder.parent().child('button', 'submit');

                    self.submit.text(IMu.string('tag-control-update'));

                    self.submit.bind('click', function() {
                        if (! self.submit.hasClass('tag-control-disabled-update'))
                            self.widget.updateTags();
                    });
                    self.submit.hide();
                }
            },

            /*
            ** display a tag on screen
            */
            displayTag: function(value, tagStatus)
            {
                var self = this;

                var tag = self.tagHolder.find('.tags').child('span', 'post-tag');
                tag.text(value);
                tag.attr('title',value);

                if (tagStatus != 'approved')
                {
                    tag.addClass('unauthorised-tag');

                    if (tagStatus == 'suggested')
                    {
                        var deleteTag = tag.child('span','delete-tag');
                        deleteTag.text(' (x)');

                        deleteTag.click(function()
                        {
                            self.widget.doDropSuggestedTag(value);
                        });
                    }
                }
            },

            /*
            ** redraw the tag display
            */
            redrawTagDisplay: function()
            {
                var self = this;

                var noSuggestedTags = true;

                self.tagHolder.find('.tags').empty();

                if (self.widget.options['showApprovedTags'])
                {
                    jQuery.each(self.widget.getApprovedTags(), function(idx, value) {
                        self.displayTag(value, 'approved');
                    });
                }
                if (self.widget.options['showCandidateTags'])
                {
                    jQuery.each(self.widget.getCandidateTags(), function(idx, value) {
                        self.displayTag(value, 'candidate');
                    });
                }

                jQuery.each(self.widget.getSuggestedTags(), function(idx, value) {
                    self.displayTag(value, 'suggested');
                    noSuggestedTags = false;
                });

                if (noSuggestedTags)
                {
                    if (self.submit != undefined)
                    {
                        self.submit.addClass('tag-control-disabled-update');
                        self.submit.hide();
                    }
                }
                else
                {
                    if (self.submit != undefined)
                    {
                        self.submit.removeClass('tag-control-disabled-update');
                        self.submit.show();
                    }
                }
            },


            /*
            ** display information on a status to the user
            */
            showUserMessage: function(status, data)
            {
                var self = this;
                if (status == undefined)
                    status = 'tag-control-unknown-error';
                var msg = IMu.string(status + '-msg') + '. ' +  data;
                alert(msg);
            },


            /**
            ** clean up input control to allow new tags to be suggested
            */
            tidyUpdateControls: function()
            {
                var self = this;

                var inputBox = jQuery(self.widget.owner).find('input');
                if (inputBox != undefined)
                    inputBox.val('');
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/capture-control.js
*/
(function(theme)
{
    theme.views.register('capture-control', 'control',
    {
        _source: 'shared/common/capture-control',

        all:
        {
            _construct: function()
            {
                this._super.apply(this, arguments);

                this.buttons =          undefined;
                this.dropzone =         undefined;  // the area to drag-drop resources
                this.fileSystemBtn =    undefined;  // button to open filesystem browser
                this.promptArea =       undefined;  // prompts the user for interaction
                this.resourceDisplay =  undefined;  // where resources are displayed
                this.resourceSelection = undefined; // where the user can select
                                                    // a resource to display
            },

            _create: function()
            {
                this.holder = this.widget.owner.child('div', 'holder');
                this.content = this.holder.child('div', 'content');
                
                this._createButtons();
                this._createDropzone();
                this._createResourceDisplay();
                this._createResourceSelection();
            },

            /* Creates the controls for the user to interact with the widget.
            */
            _createButtons: function()
            {
                var widget = this.widget;
                
                if (widget.getOption('readOnly') || ! widget.getOption('useCaptureButtons'))
                    return;
                
                this.buttons = this.holder.child('div', 'buttons');
                var button;

                button = this.fileSystemBtn = this.buttons.child('button');
                button.text(IMu.string('capture-control-file-input'));

                IMu.FileAPI.FSButton(button, function(files)
                {
                    widget.addFiles(files);
                });
            },

            /* Creates an area that the user can drag and drop resources
            ** to be added to the widget.
            */
            _createDropzone: function()
            {
                var widget = this.widget;

                if (widget.getOption('readOnly') || ! widget.getOption('useCaptureDropzone'))
                    return;

                this.dropzone = this.content.child('div',
                    'imu-capture-control-dropzone');

                if (! this.promptArea)
                    this.promptArea = this.dropzone.child('div', 'prompt-area');

                var div = this.promptArea.child('div', 'hover-text');
                div.child('div').text(IMu.string('capture-control-hovertext'));

                IMu.FileAPI.dnd(this.dropzone, function(files)
                {
                    widget.addFiles(files);
                });
            },

            /* Creates an area to render a resource or resources
            ** for viewing or interaction by the user.
            */
            _createResourceDisplay: function()
            {
                if (! this.widget.getOption('showResources'))
                    return;
               
                var parentElem;
                if (this.dropzone)
                    parentElem = this.dropzone;
                else
                    parentElem = this.content;
                
                if (! this.promptArea)
                    this.promptArea = parentElem.child('div', 'prompt-area');
               
               
                this.resourceDisplay = jQuery('<div class=' + 
                    '"imu-capture-control-resources"></div>');
                this.resourceDisplay.insertBefore(this.promptArea);

                var div = this.promptArea.child('div', 'no-items-text').child('div');

                if (this.buttons && this.dropzone)
                    div.text(IMu.string('capture-control-drag-or-select-prompt'));
                else if (this.buttons)
                    div.text(IMu.string('capture-control-select-prompt'));
                else if (this.dropzone)
                    div.text(IMu.string('capture-control-drag-prompt'));
                else
                    div.text(IMu.string('capture-control-no-files-to-display'));
            },

            /* Creates the selection tool for users to select
            ** a resource to be displayed.
            **
            ** This is an interface method to be implemented
            ** by inherited classes.
            **
            */
            _createResourceSelection: function()
            {
                this.resourceSelection = this.content.child('div',
                    'imu-capture-control-resource-selection');
            },

            /* Adds to the resources displayed.
            */
            addResource: function(resourceData, callback)
            {
                var widget = this.widget;
               
                /* detaching and inserting resourceDisplay to force repaint 
                ** in internet explorer and Edge.
                ** without it there would be rendering issues.
                */
                this.resourceDisplay.detach(); 
                
                var resource = this.resourceDisplay.child('div', 'resource'); 
                var nameCell = resource.child('div', 'text-cell name');
                var a = nameCell.child('a');

                var removeCell = resource.child('div', 'button-cell remove');
                var button = removeCell.child('button');
                button.attr('title', IMu.string('capture-control-remove'));

                button.click(function()
                {
                    widget.removeResource(resourceData);
                });
                
                var img = button.child('img');
                var src = IMu.Request.getURL('Image') + '&name=cross';
                img.attr('src', src);
                
                this.setResourceValues(resource, resourceData);
                
                this.resourceDisplay.insertBefore(this.promptArea);
                
                if (callback)
                    callback(resource);
            },

            /* Redraws resource after title and download information
            ** has been fetched from the server.
            */
            setResourceValues: function(elem, data)
            {
                var widget = this.widget;

                var name = data.name || '';
                if (! name && data.irn)
                    name = IMu.string('capture-control-retrieving');
                 
                var a = jQuery(elem).find(".name > a")
                a.text(name);
                a.attr('title', name);

                if (data.file)
                {
                    // Resource is a local file
                    a.removeAttr('href');
                    a.removeAttr('download');
                }
                else if (data.url)
                {
                    // Resource is on another server
                    a.attr('href', data.url);
                    a.attr('download', name);
                }

                var button = jQuery(elem).find(".button-cell.remove > button");
                if (this.widget.getOption('readOnly') || data.readOnly)
                    button.hide();
                else
                    button.css('display','');
             },

            /* Clears all resources displayed.
            */
            clearResources: function()
            {
                this.resourceDisplay.empty();
            },

            removeResource: function(resource)
            {
                /* detaching and inserting resourceDisplay to force repaint in 
                ** internet explorer and Edge.
                ** without it there would be rendering issues.
                */
                this.resourceDisplay.detach(); 
                resource.remove();
                this.resourceDisplay.insertBefore(this.promptArea);
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/image-capture-control.js
*/
(function(theme)
{
    theme.views.register('image-capture-control', 'control',
    {
        _source: 'shared/client/image-capture-control',

        all:
        {
            _construct: function()
            {

                var self = this;

                self._super.apply(self, arguments);
            },
            _create: function()
            {

                var self = this;

                self._super();
                var ic = self.widget.owner; 
                
                var fileApi = self.content.child('div','js-fileapi-wrapper upload-btn');
                var upload = fileApi.child('div','upload-btn__txt');

                var imageInput = upload.child('input type="file"', 'imu-image-capture-input');
                imageInput.attr('accept', 'image/*;capture=camera');
                imageInput.attr('id','image-input');

                if(self.widget.getOption('allowMultiple') == true)
                    imageInput.attr('multiple','');

                imageInput.css('opacity','0');
                imageInput.css('height','1px');
                imageInput.css('width','1px');
                var button = upload.child('label','upload-button');
                var dummy = button.child('button');
                button.attr('for','image-input');
                dummy.text(IMu.string('image-capture-input'));

                button.click(function()
                {
                    imageInput.click();
                });

                var filePath = upload.child('div','file-path');
              
                var onFileAPILoaded = function ()
                {
                        self.ready = true;
                        FileAPI.event.dnd(ic[0],function(over){},function(files)
                        {
                            onImageAdd(files);
                        });

                        FileAPI.event.on(imageInput[0], 'change', function(evt)
                        {
                            var files = FileAPI.getFiles(evt);
                            onImageAdd(files);
                        });
                };
 
                if (!IMu.FileAPI._ready)
                {
                    IMu.event.on('imu-FileAPI-loaded',function()
                    {
                         onFileAPILoaded();
                    });
                 }
                 else
                 {
                    onFileAPILoaded();
                 }

                //check if multiple images can be selected.
                var onImageAdd = function (files)
                {
                    if (self.ready)
                    {
                        FileAPI.each(files,function(file)
                        {
                            var imageType = /image.*/;
                            if (!file.type.match(imageType))
                                return false;
                            self.widget.imageControl.isMultiple = true;

                            FileAPI.readAsDataURL(file,function(evt)
                            {
                                if (evt.type == 'load')
                                {
                                    self.widget.imageControl.loadCapturedImageUsingData(evt.result,file.name);
                                    self.widget.encodedImage = evt.result;
                                }
                                else if (evt.type == 'progress')
                                {
                                }
                                else
                                {
                                    FileAPI.Image(file).get(function (err,img) {
                                        if (!err)
                                        {
                                            var dataURL = img.toDataURL("image/png");
                                            IMu.log('Data url for image:' + dataURL);
                                            self.widget.imageControl.loadCapturedImageUsingData(dataURL,file.name);
                                        }
                                        else
                                        {
                                            file.xhr = FileAPI.upload({
                                                url: 'imu/requests/client/ctrl.php',
                                                files: {files: file},
                                                complete: function (err,xhr) {
                                                        var response = JSON.parse(xhr.responseText);
                                                        var dataURL = response.images.files.dataURL;
                                                        var name = xhr.files[0].name;
                                                        self.widget.imageControl.loadCapturedImageUsingData(dataURL,name);
                                                    }
                                                });
                                        }
                                    });
                                 }
                            });
                        });
                    }
                };
                var preview = self.content.child('div', 'preview');
                preview.css('height', '100%');
                preview.css('width', '100%');
                preview.css('clear', 'both');

                var controlHeight = 400;
                if (self.widget.options.imageControlHeight)
                    controlHeight = self.widget.options.imageControlHeight;

                var imageControl = self.widget.imageControl = preview.IMu('image-control',
                {
                    'height': controlHeight,
                    onChange: self.widget.options.onChange,
                    isMultiple: true,
                    defaultContext: self.getOption('defaultContext'),
                    defaultPort: self.getOption('defaultPort')
                });


                //imageControl.addEventListener("drop", drop, false);
                //
                ic.on(
                    'dragover',
                    function(e) 
                    {
                        e.preventDefault();
                        e.stopPropagation();
                    }
                )

                ic.on(
                    'dragcenter',
                    function(e) 
                    {
                        e.preventDefault();
                        e.stopPropagation();
                    }
                )
                
                if(!self.widget.imageControl.view)
                    self.widget.imageControl.createView();

            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/image-control.js
*/
(function(theme)
{
    theme.views.register('image-control', 'control',
    {
        _source: 'shared/common/image-control',

        all:
        {
            _construct: function()
            {
                var self = this;

                self._super.apply(self, arguments);

                self.imageLayer = undefined;
                self.vectorLayer = undefined;

                self.selectedPolygon = undefined;

                self.imagesAudit = {};
            },
            _create: function()
            {
                var self = this;

                self._super();

                //EVENT HANDLERSs
                var baseLayerChanged = function(event)
                {
                    IMu.log('image-control : baseLayerChanged - layer ID {0}', event.layer.id);
                    IMu.log('image-control : baseLayerChanged - baseLayer ID {0}', event.object.baseLayer.id);

                    var layerId = event.object.baseLayer.id;

                    event.layer.map.zoomToMaxExtent();
                    self.clearVectorFeatures();

                    if(layerId in self.imagesAudit)
                    {
                        if (self.imagesAudit[layerId].state || self.imagesAudit[layerId].polygons)
                        {
                            self.widget.setProperties(self.imagesAudit[layerId]);
                        }
                    }
                }

                var change = function(event, type)
                {
                    IMu.log('image-control : change - {0} change triggered', event.type);
                    var layerId = undefined;

                    if(this.baseLayer)
                        layerId = this.baseLayer.id;
                    else if (this.map.baseLayer)
                        layerId = this.map.baseLayer.id;

                    if (layerId in self.imagesAudit)
                    {
                        self.imagesAudit[layerId].state = self.getState();
                        self.imagesAudit[layerId].polygons = self.getPolygons();
                    }

                    self.widget.doChange();
                }

                var layerChanged = function(event, type)
                {
                    IMu.log('image-control : layerChanged triggered');

                    var layerId = event.layer.id;
                    var baseLayerId = this.baseLayer.id;
                    var name = event.layer.name;
                    var vis = event.layer.visibility;

                    if(vis == false)
                    {
                        // Get Current state and Polygons
                        IMu.log('image-control : mapChangeLayer - hide {0}({1})',layerId,name);

                        var state = self.getState();
                        var polygons = self.getPolygons();

                        if (layerId in self.imagesAudit)
                        {
                            self.imagesAudit[layerId].state = state;
                            self.imagesAudit[layerId].polygons = polygons;
                        }
                        if(baseLayerId in self.imagesAudit )
                        {
                            if (self.imagesAudit[baseLayerId].state || self.imagesAudit[baseLayerId].polygons)
                            {
                                self.widget.setProperties(self.imagesAudit[baseLayerId]);
                            }
                        }
                        else
                        {
                            self.imagesAudit[layerId] = {
                                "state": state,
                                "polygons": polygons
                            };
                        }
                    }
                    else if (vis == true)
                    {
                        // set properties on new image
                        IMu.log('image-control : mapChangeLayer - show {0}({1})',layerId,name);

                        if (layerId in self.imagesAudit)
                        {
                            self.widget.setProperties(self.imagesAudit[layerId]);
                        }
                    }
                }

                var onVectorSelected = function(feature)
                {
                    IMu.log('image-control : onVectorSelected triggered');

                    // var geoJson = new OpenLayers.Format.GeoJSON();
                    // var str = geoJson.write(feature, true);
                    // var obj = JSON.parse(str);
                    // self.setPolygon = obj.geometry.coordinates[0];
                }

                var removeCurrentLayer = function()
                {
                    if (self.imageLayer)
                    {
                        var baseLayerId = self.imageLayer.baseLayer.id;

                        for (var i = 0; i < self.imageLayer.layers.length; i++) 
                        {
                            var layer = self.imageLayer.layers[i];

                            if (baseLayerId == layer.id)
                            {
                                self.imageLayer.removeLayer(layer);
                                delete self.imagesAudit[layer.id];

                                if(layer.id in self.imagesAudit)
                                {
                                    self.imageLayer.setBaseLayer(layer);
                                    break;
                                }
                            }
                        };

                        for (var i = 0; i < self.widget.images.length; i++) 
                        {
                            var image = self.widget.images[i]

                            if (baseLayerId == image.id)
                            {
                                self.widget.images.splice(i,1);
                                break;
                            }
                        };
                        self.widget.autoHideLayerSelect();
                    }
                }

                var removePolygon = function()
                {
                    if (self.imageLayer && self.vectorLayer)
                    {
                        if (self.vectorLayer.features.length == 0)
                            return;
                        if (self.vectorLayer.selectedFeatures.length == 0)
                            return;

                        var selectedFeatures = self.vectorLayer.selectedFeatures;

                        while (selectedFeatures.length > 0) 
                        {
                            var feature = selectedFeatures[0];
                            feature.destroy();
                        }
                    }
                }

                var height = self.content.height();
                if (! height || height < 100)
                {
                    var height = self.widget.getOption('height');
                    if (! height)
                        height = 400;

                    self.content.height(height);
                }

                self.imageLayer = new OpenLayers.Map(self.content[0],
                {
                    units: 'pixels'
                });

                // IMAGE LAYER EVENTS
                self.imageLayer.events.on(
                {
/* The next 2 lines were removed to fix bug outlined in Jira IMU-318
** Though it introduced another issue where image-capture-control would not
** mark the form as being edited.
** As such, the lines have been re-added.
** Image capture should be investigated to see if we can trigger the change
** event after a user successfully adds an image.
*/
                    "moveend": change,
                    "zoomend": change,
                    "changebaselayer": baseLayerChanged,
                    "changelayer": layerChanged
                });

                self.vectorLayer = new OpenLayers.Layer.Vector("Vector Layer",
                {
                    'displayInLayerSwitcher': false
                });

                self.vectorLayer.events.on(
                {
                    "featuremodified": change,
                    "featureselected" : onVectorSelected
                });

                //CONTROLS
                var removeCurrentLayer = new OpenLayers.Control.Button(
                {
                    title: "Remove Layer",
                    trigger: removeCurrentLayer,
                    type: OpenLayers.Control.TYPE_BUTTON,
                    displayClass: "olControlRemoveCurrentLayer"
                })

                var navigationControl = new OpenLayers.Control.Navigation(
                    {
                        title: "Navigation",
                        displayClass: 'olControlNavigation'
                    });

                var modifyControl = new OpenLayers.Control.ModifyFeature(self.vectorLayer,
                {
                    title: "Edit Polygons",
                    'displayClass': 'olControlDrawFeaturePoint'
                });
                modifyControl.mode = OpenLayers.Control.ModifyFeature.RESHAPE;
                modifyControl.mode |= OpenLayers.Control.ModifyFeature.ROTATE;
                modifyControl.mode |= OpenLayers.Control.ModifyFeature.RESIZE;
                modifyControl.mode &= ~OpenLayers.Control.ModifyFeature.RESHAPE;
                modifyControl.mode |= OpenLayers.Control.ModifyFeature.DRAG;
                modifyControl.mode &= ~OpenLayers.Control.ModifyFeature.RESHAPE;

                modifyControl.events.on(
                {
                    "featuremodified": change
                });

                var removePolygon = new OpenLayers.Control.Button(
                {
                    title: "Remove Polygon/s",
                    trigger: removePolygon,
                    type: OpenLayers.Control.TYPE_BUTTON,
                    displayClass: "olControlRemovePolygon"
                });

                var polygonControl = new OpenLayers.Control.DrawFeature(self.vectorLayer, OpenLayers.Handler.Polygon,
                {
                    title: "Draw Polygons",
                    'displayClass' : 'olControlDrawFeaturePolygon'
                });

                polygonControl.events.on(
                {
                    "beforefeatureadded": change,
                    "featureadded": change,
                    "featuremodified": change
                });

                var panelControls = [
                    removeCurrentLayer,
                    navigationControl,
                    modifyControl,
                    removePolygon,
                    polygonControl
                ];

                var toolbar = new OpenLayers.Control.Panel(
                {
                    displayClass: 'olControlEditingToolbar',
                    defaultControl: panelControls[0]
                });
                toolbar.addControls(panelControls);

                self.imageLayer.addControls(
                [
                    toolbar
                ]);

                var options = {
                    clickout: true, toggle: false,
                    multiple: false, hover: false,
                    toggleKey: "ctrlKey", // ctrl key removes from selection
                    multipleKey: "altKey", // shift key adds to selection
                    box: true
                };

                var selectFeature = new OpenLayers.Control.SelectFeature(self.vectorLayer, options);
                self.imageLayer.addControl(selectFeature);
                //selectFeature.activate();

                var layerSwitcher = new OpenLayers.Control.LayerSwitcher(
                {
                    'ascending': false
                });
                self.imageLayer.addControl(layerSwitcher);
            },

            addLayer: function(graphic)
            {
                var self = this;

                self.clearImageLayer();

                self.imageLayer.addLayers([graphic, self.vectorLayer]);
                self.imageLayer.zoomToMaxExtent();
            },

            clearImageLayer: function()
            {
                var self = this;

                if (self.imageLayer.layers.length > 0)
                {
                    var i = 0;
                    while (self.imageLayer.layers[i])
                    {
                        self.imageLayer.removeLayer(self.imageLayer.layers[i]);
                    }

                    self.clearVectorFeatures();

                    var controls = self.imageLayer.controls[4].controls;
                    // set navigation to active control
                    controls[0].activate(); //navigation
                    controls[1].deactivate(); //polygon
                    controls[2].deactivate(); //edit polygon
                }
            },

            clearVectorFeatures: function()
            {
                var self = this;
                if (self.imageLayer && self.vectorLayer)
                {
                    self.vectorLayer.removeAllFeatures();
                }
            },

            displayImageUsingData: function(data, name, callback)
            {
                var self = this;

                var bounds = undefined;
                var viewPort = self.imageLayer.getViewport();

                var vh = jQuery(viewPort).height();
                var vw = jQuery(viewPort).width();

                var i = new Image();

                i.onload = function()
                {
                    var scale = 1;
                    var graphic;

                    if (this.width && this.height)
                    {
                        bounds = new OpenLayers.Bounds(0, 0, this.width, this.height);
                        var aspectWidth = vw / this.width;
                        var aspectHeight = vh / this.height;
                        scale = Math.min(aspectWidth, aspectHeight);

                        graphic = new OpenLayers.Layer.Image(
                            name,
                            data,
                            bounds,
                            new OpenLayers.Size(this.width * scale, this.height * scale)
                        );
                    }
                    else
                    {
                        bounds = new OpenLayers.Bounds(0, 0, 10, 10);

                        graphic = new OpenLayers.Layer.Image(
                            name,
                            data,
                            bounds,
                            new OpenLayers.Size(vw * 0.9, vh * 0.9)
                        );
                    }

                    if (self.widget.isMultiple == false)
                    {
                        self.addLayer(graphic);
                    }
                    else
                    {
                        self.imageLayer.addLayers([graphic, self.vectorLayer]);
                    }
                    self.imageLayer.updateSize();

                    if (callback && typeof(callback) == 'function')
                    {
                        callback(graphic);
                    }
                };

                i.src = data;
            },

            displayImageUsingKey: function(key, callback)
            {
                var self = this;

                var bfWidth = self.widget.getOption('bestFitWidth');

                if (! bfWidth)
                    bfWidth = 1500;

                var mm = new IMu.Request.Multimedia();
                mm.addModifier('format', 'jpeg');
                mm.addFilter('kind','resolution');
                mm.addFilter('width', 'bf',bfWidth);
                //mm.addModifier('width','4000')
                mm.setKey(key);
                
                var urlParams = "";
                var context = self.getOption('defaultContext');
                var port = self.getOption('defaultPort');

                if(context)
                    urlParams += "&context=" + context;
                if(port)
                    urlParams += "&port=" + port;
                
                mm.fetchInfo(function(info)
                {
                    var url = mm.getURL() + urlParams;
                   
                    if (info.width < (bfWidth-10))
                    {
                        var d = new IMu.App.Dialogue();
                        d.setMessage('Fetching new resolution for image ...');
                        d.show();

                        var mm2 = new IMu.Request.Multimedia();
                        mm2.addModifier('format', 'jpeg');
                        mm2.addModifier('width',bfWidth);
                        mm2.addModifier('allowEnlarge', 'no');

                        mm2.setKey(info.key);

                        mm2.fetchInfo(function(info)
                        {
                            var url = mm2.getURL() + urlParams;

                            var graphic = self.addMMImageToLayer(info,url);

                            d.hide();

                            // Update openlayers size in case image-control has 
                            // been resized since image load started.
                            self.imageLayer.updateSize();

                            if (callback && typeof(callback) == 'function')
                            {
                                callback(graphic);
                            }
                        });
                    }
                    else
                    {

                        var graphic = self.addMMImageToLayer(info,url);

                        // Update openlayers size in case image-control has 
                        // been resized since image load started.
                        self.imageLayer.updateSize();

                        if (callback && typeof(callback) == 'function')
                        {
                            callback(graphic);
                        }
                    }

                });
                
                // This happens when there is no resolution 
                // Just the master image and the thumbnail.
                mm.onError = function(response)
                {
                    var d = new IMu.App.Dialogue();
                    d.setMessage('Fetching thumbnail ...');
                    d.show();

                    var mmThumbnail = new IMu.Request.Multimedia();
                    mmThumbnail.addFilter('kind', 'thumbnail');

                    mmThumbnail.setKey(key);

                    mmThumbnail.fetchInfo(function(info)
                    {

                        var url = mmThumbnail.getURL() + urlParams;

                        var graphic = self.addMMImageToLayer(info,url);

                        d.hide();

                        // Update openlayers size in case image-control has 
                        // been resized since image load started.
                        self.imageLayer.updateSize();

                        if (callback && typeof(callback) == 'function')
                        {
                            callback(graphic);
                        }
                    });

                    // If a thumbnail can't be fetched, we remove the dialog
                    // overlay so the user can continue modifying/editing
                    // the record. Can happen for PDF's and broken multimedia
                    // images. JIRA IMu-338.
                    mmThumbnail.onError = function(response)
                    {
                        d.hide();
                        callback(undefined);
                    };
                };
            },

            addMMImageToLayer: function(info,url)
            {
                var self = this;

                var labelText = info.key;

                if (info.identifier)
                    labelText = info.identifier;

                var viewPort = self.imageLayer.getViewport();
                var vh = jQuery(viewPort).height();
                var vw = jQuery(viewPort).width();

                var aspectWidth = vw / info.width;
                var aspectHeight = vh / info.height;
                var scale = Math.min(aspectWidth, aspectHeight);

                var graphic = new OpenLayers.Layer.Image(
                    labelText,
                    url,
                    new OpenLayers.Bounds(0, 0, info.width, info.height),
                    new OpenLayers.Size(info.width * scale, info.height * scale)
                );

                if (self.widget.isMultiple ==  false)
                {
                    self.addLayer(graphic);
                }
                else
                {
                    self.imageLayer.addLayers([graphic, self.vectorLayer]);
                }

                return(graphic);
            },

            getPolygon: function()
            {
            },

            getPolygons: function()
            {
                var self = this;

                if (self.imageLayer && self.vectorLayer)
                {
                    var geoJson = new OpenLayers.Format.GeoJSON();
                    var str = geoJson.write(self.vectorLayer.features, true);
                    var obj = JSON.parse(str);
                    if (obj.features.length > 0)
                    {
                        var polygons = [];
                        for (var i = 0; i < obj.features.length; i++)
                        {
                            polygons.push(obj.features[i].geometry.coordinates[0]);
                        }
                    }

                    return polygons;
                }
            },

            getState: function()
            {
                var self = this;

                if (self.imageLayer)
                {
                    var state = new Object();
                    state.x = self.imageLayer.center.lon;
                    state.y = self.imageLayer.center.lat;
                    state.zoom = self.imageLayer.getZoom();
                }

                return state;
            },

            setImageLatLon: function(x, y)
            {
                var self = this;

                if (self.imageLayer)
                {
                    var lonlat = new OpenLayers.LonLat(x, y);
                    self.imageLayer.panTo(lonlat);
                }
            },

            setZoomLevel: function(level)
            {
                var self = this;

                if (self.imageLayer)
                {
                    self.imageLayer.zoomTo(level);
                }
            },

            setPolygon: function(coordinates)
            {
                var self = this;

                if (self.imageLayer && self.vectorLayer)
                {
                    //create a polygon feature from a linear ring of points
                    var pointList = [];

                    for (var i = 0; i < coordinates.length; i++)
                    {
                        var coordinate = coordinates[i];
                        //TODO 
                        //need to make sure that coordinates are of type float
                        //need to make sure that each array has two coordinates (x,y)
                        pointList.push(new OpenLayers.Geometry.Point(coordinate[0], coordinate[1]));
                    }
                    var linearRing = new OpenLayers.Geometry.LinearRing(pointList);
                    var polygonFeature = new OpenLayers.Feature.Vector(
                        new OpenLayers.Geometry.Polygon([linearRing]));
                    self.vectorLayer.addFeatures(polygonFeature);
                }
            }


        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/button-control.js
*/
(function(theme)
{
    theme.views.register('button-control',
    {
        _source: 'shared/common/button-control',

        all:
        {
            _construct: function()
            {
                this._super.apply(this, arguments);
                this.states = [];
            },

            _create: function()
            {
                this._super.apply(this, arguments);
                
                var self = this;

                var owner = self.widget.owner;
                self.button = owner.child('button');
                if (self.widget.options.name)
                {   
                    var name = self.widget.options.replace(/ /g, "-");
                    owner.addClass(name);
                }
                self.button.click(function() { self.onClick() });

                var states = self.widget.states;
                for (var i = 0; i < states.length; i++)
                    self.addState(states[i]);
            },
                
            addState: function(state)
            {
                var button = this.button;
                var table = button.child('div', 'table');
                table.css
                ({
                    "table-layout": "fixed",
                    "-webkit-touch-callout": "none",
                    "-webkit-user-select": "none",
                    "-khtml-user-select": "none",
                    "-moz-user-select": "none",
                    "-ms-user-select": "none",
                    "user-select": "none"
                });

                var index = this.states.length;
                table.addClass('state state-' + (index+1));
                if (state.name !== undefined)
                    table.addClass(state.name.replace(/ /g, "-"));
                
                this.states[index] = table;
                this.states[index].widget = this.widget.states[index];
                this.widget.states[index].view = this.states[index];

                var tr = table.child('div', 'table-row');

                var layout = state.layout;
                if (! IMu.Type.isArray(layout))
                    layout = [ layout ];

                for (var i = 0; i < layout.length; i++)
                {
                    var elem = layout[i];

                    if (elem === undefined)
                    {
                        tr.child('div', 'table-cell empty-element');
                        break;
                    }
                    if (elem['type'] === undefined || elem['value'] === undefined)
                        break;
                    
                    var cell = tr.child('div', 'table-cell ' + elem['type'] + '-element');
                    if (elem['name'] !== undefined)
                        cell.addClass(elem['name']);

                    var div = cell.child('div');
                    div.css(
                    {
                        position: 'relative',
                        top: '0',
                        width: '100%'
                    });
                    if (elem['type'] == 'text')
                        div.text(IMu.string(elem['value']));
                    else if (elem['type'] == 'image')
                    {
                        div.css('height', '100%');

                        var tbl = div.child('div', 'table');
                        tbl.css('table-layout', 'fixed');

                        var td = tbl.child('div',
                            'table-row').child('div', 'table-cell');
                        var graphic = td.child('div', 'graphic');
                        graphic.css(
                        {
                            bottom: '0',
                            left: '0',
                            position: 'absolute',
                            right: '0',
                            top: '0'
                        });
                        var img = graphic.child('img');

                        if (elem['value'] !== undefined)
                            img.attr('src', elem['value']);
                    }

                    if (this.widget.currentState != index)
                        table.css('display', 'none');
                }

                if (state.classes !== undefined)
                    for (var i = 0; i < state.classes.length; i++)
                        table.addClass(state.classes[i]);
            },

            disable: function(toggle)
            {
                //TODO:
                if (toggle || toggle === undefined)
                    this.widget.owner.addClass('disabled');
                else
                    this.widget.owner.removeClass('disabled');
            },

            setState: function(index)
            {
                if (this.states[index] === undefined)
                    return;
                
                for (var i = 0; i < this.states.length; i++)
                    this.states[i].css('display', 'none');
               this.states[index].css('display', 'table');

//               this.states[index].widget.onSelect();
            },

            // Private
            onClick: function()
            {
                this.widget.doClick();
            }
        }
    });
})(IMu.Themes.shared);

