(function(theme)
{
    theme.views.register('geolocate-control', 'control',
    {
        _source: 'shared/common/geolocate-control',

        all:
        {
            _create: function()
            {
                this._super.apply(this, arguments);

                var self = this;

                var widget = self.widget;

                var options =
                {
                    select: function(e, ui)
                    {
                        widget.doSelect(ui.item);
                        widget.irn = ui.item.irn;
                    }
                };
                var table = self.content.child('table');
                var tbody = table.child('tbody','full-width');
                var tr = table.child('tr');
                var td = tr.child('td');
                self.control = td.child('input type="text"');
                self.control.on('textchange', function()
                {
                    self.widget.doChange();
                });
                self.setup();
                self.contentHint = '';
                if (self.hint)
                {
                    self.control.attr('title', self.hint);
                    self.contentHint = '(' + self.hint + ')';
                    self.control.on('focus', function()
                    {
                        if (self.control.val() == self.contentHint)
                        {
                            self.control.val('');
                            self.control.removeClass('hint');
                        }
                    });
                    self.control.on('blur', function()
                    {
                        if (self.control.val() == '')
                        {
                            self.control.val(self.contentHint);
                            self.control.addClass('hint');
                        }
                    });
                    self.control.on('blur');
                }
                self.control.on('keypress', function(e)
                {
                    if (e.keyCode == 13)
                        self.widget.doEnter();
                });
                self.control.on('barcode-scanned', function(e, info)
                {
                    self.setValue(info.value);
                    self.widget.doChange();
                });

                if (widget.options.minLength !== undefined)
                    options.minLength = widget.options.minLength;
                var td = tr.child('td');
                var url = IMu.Request.getURL('Image') + '&name=tulane_geolocate';

                var button = td.child('input type="image"','geolocate-button');
                button.attr('src',url);
                button.bind('click',function()
                {
                    var text = self.getValue();
                    var fullURL = self.widget.options.URL;
                    if (text)
                        fullURL += '?points=' + text;
                    self.openWindow(fullURL);
                });

                /*
                var div = td.child('button','geolocate-button');
                self.external = div.IMu('button-control');
                self.external.addState(
                {
                    layout:
                    {
                        type: 'graphic',
                        value: url
                    },
                    onClick: function ()
                    {
                        var text = self.getValue();
                        var fullURL = self.widget.options.URL;
                        if (text)
                            fullURL += '?points=' + text;
                        self.openWindow(fullURL);
                    }
                });
                */

                /* Add event listener for storage locations */
                $(window).bind('storage', function (e)
                {
                    var key = window.location + "-imu-geolocate-data";
                    if (e.originalEvent.key !== key)
                        return;
                    var value = window.localStorage.getItem(window.location + "-imu-geolocate-data");
                    self.control.val(value);
                });
            },

            openWindow: function(url)
            {
                var self = this;
                var html = '<html><head></head>';
                html += '<body><iframe width="100%" height="100%" src="' + url + '"></iframe>';
                html += '<script type="text/javascript">';
                html += 'window.addEventListener("message", function(evt){if (evt.origin != "http://www.museum.tulane.edu") return; else {window.localStorage.setItem(window.location + "-imu-geolocate-data",evt.data);window.close()};}, false);'
                html += '</script>';
                html += '</body></html>';
                self.popup = window.open('', 'Geolocate');
                self.popup.document.write(html);
            },
            /*!
            ** Gets the current value from the control.
            **
            ** @returns value
            **   The current value of the control.
            */
            getValue: function()

            {
                var value = this.control.val();
                if (value == this.contentHint)
                    value = undefined;
                var locObject = {};
                var array = value.split('|');
                if (array.length > 0)
                {
                    
                }
                return value;
            },

            /*!
            ** Sets a value of the control.
            **
            ** @param value
            **   The value to set.
            */
            setValue: function(value)
            {
                this.control.val(value);
                if (this.contentHint)
                {
                    if (this.control.val() != '')
                        this.control.removeClass('hint');
                    else
                    {
                        this.control.val(this.contentHint);
                        this.control.addClass('hint');
                    }
                }
            }


        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/grid.js
*/
(function(theme)
{
    theme.views.register('grid',
    {
        _source: 'shared/common/grid',

        all:
        {
            _construct: function()
            {
                this._super.apply(this, arguments);

                this.table = undefined;
                this.thead = undefined;
                this.tbody = undefined;
                this.items = [];
            },

            _create: function()
            {
                this._super.apply(this, arguments);

                var self = this;

                var widget = self.widget;
                self.table = widget.owner.child('table');

                if (widget.hasHeadings())
                {
                    var thead = self.table.child('thead');
                    var tr = thead.child('tr', 'headings');

                    if (self.widget.options.rowNumbers)
                        tr.child('th');

                    for (var i = 0; i < widget.columns.length; i++)
                    {
                        (function(n)
                        {
                            var column = widget.columns[n];
                            column.element = tr.child('th');
                            column.element.addClass('heading');
                            column.element.addClass('heading-' + (n + 1));
                            if (column.name)
                                column.element.addClass('heading-' + column.name);
                            column.element.bind('click', function()
                            {
                                self.widget.columnClicked(column);
                            });
                        })(i);
                    }
                    self.updateColumns();
                }

                self.tbody = this.table.child('tbody');

                // Catch enter key here
                this.table.bind('keydown', function(e)
                {
                    if (e.keyCode == 13)
                    {
                        return false;
                    }
                });
            },

            clear: function()
            {
                this.tbody.empty();
                this.items = [];
            },

            create: function(index, row)
            {
                var self = this;

                var tr = jQuery('<tr/>');
                tr.addClass('row');
                for (var i = 0; i < row.classes.length; i++)
                    tr.addClass(row.classes[i]);
                tr.bind('click', function()
                {
                    self.widget.rowClicked(row);
                });

                if (index >= 0 && index < self.items.length)
                    self.items[index].tr.before(tr);
                else
                {
                    self.tbody.append(tr);
                    index = self.items.length;
                }

                var item =
                {
                    tr: tr,
                    row: row
                };
                self.items.splice(index, 0, item);

                if (self.widget.options.rowNumbers)
                    item.tr.child('td', 'row-number');
                for (var i = 0; i < item.row.cells.length; i++)
                {
                    var cell = item.row.cells[i];
                    var column = cell.column;

                    var td = item.tr.child('td');
                    td.addClass('column');
                    td.addClass('column-' + (i + 1));
                    if (column.name)
                        td.addClass('column-' + column.name);
                    cell.create(td);
                }
                if (self.widget.options.showAddRemove)
                {
                    var add = item.tr.child('td', 'add');
                    add.bind('click', function()
                    {
                        self.widget.insertRow(index + 1);
                    });
                    var image = add.child('img', 'image');
                    var url = IMu.Request.getURL('Image') + '&name=app/add';
                    image.attr('src', url);
                    image.attr('title', IMu.string('add-row-below'));

                    var text = add.child('div', 'text')
                    
                    var remove = item.tr.child('td', 'cross');
                    remove.bind('click', function()
                    {
                        if (index == 0 && self.widget.rows.length == 1)
                        {
                            return;
                        }
                        self.widget.removeRow(index);
                    });
                    var img = remove.child('img');
                    var url = IMu.Request.getURL('Image') + '&name=cross';
                    img.attr('src', url);
                    img.attr('title', IMu.string('remove-row'));
                }
                self.updateRowNumbers(index);
            },

            remove: function(index)
            {
                if (index < 0 || index >= this.items.length)
                    return;
                var item = this.items[index];
                item.tr.remove();
                this.items.splice(index, 1);
                this.updateRowNumbers(index);
            },

            updateColumns: function()
            {
                for (var i = 0; i < this.widget.columns.length; i++)
                {
                    var column = this.widget.columns[i];

                    var text = '';
                    if (column.heading)
                        text += column.heading;
                    if (column.sorted)
                    {
                        if (text != '')
                            text += ' ';
                        if (column.sorted == 'descending')
                            text += '&uarr;';
                        else
                            text += '&darr;';
                    }
                    column.element.html(text);
                }
            },

            updateRowNumbers: function(from)
            {
                if (! this.widget.options.rowNumbers)
                    return;

                for (var i = from; i < this.items.length; i++)
                {
                    var item = this.items[i];
                    var tr = item.tr;
                    var td = tr.children('.row-number');
                    td.text(i + 1);
                }
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/graph.js
*/
(function(theme)
{
    theme.views.register('graph', 'control',
    {
        _source: 'shared/common/graph',

        all:
        {
            _construct: function()
            {

                var self = this;

                self._super.apply(self, arguments);

                self.svg = undefined;
            },
            _create: function()
            {
                var self = this;

                self._super();

                self.svg = self.widget.owner;

                var height = self.svg.height();
                if (!height || height < 100)
                {
                    var height = self.widget.getOption('height');

                    if (!height)
                        height = 300;
                    self.svg.height(height);
                }
            },

            drawBarChart: function(data,options)
            {
                var self = this;

                // var stringifyJSON = JSON.stringify(data);

                //var jsonData = JSON.parse(stringifyJSON);
                
                nv.addGraph(function()
                {
                    var chart = nv.models.discreteBarChart()
                        .x(function(d) { return d.label })
                        .y(function(d) { return d.value })
                        .staggerLabels(true)
                        .staggerLabels(data[0].values.length > 4)
                        .tooltips(true)
                        .showValues(true)
                        .transitionDuration(1200);

                    d3.select(self.svg.selector)
                        .datum(data)
                        .transition().duration(1200)
                        .call(chart);

                    nv.utils.windowResize(chart.update);

                    return chart;
                });
            },

            drawPieChart: function(data,options)
            {
                var self = this;

                nv.addGraph(function()
                {
                    var chart = nv.models.pieChart()
                        .x(function(d)
                        {
                            return d.label
                        })
                        .y(function(d)
                        {
                            return d.value
                        })
                        .showLabels(true)
                        .labelThreshold(.05)  //Configure the minimum slice size for labels to show up
                        .labelType("percent");
                        //.valueFormat = d3.format('f');

                    d3.select(self.svg.selector)
                        .datum(data)
                        .transition().duration(1200)
                        .call(chart);

                    return chart;
                });
            }
        }
    });
})(IMu.Themes.shared);
/* Source: ./shared/common/views/manager.js
*/
(function(theme)
{
    theme.views.register('manager', 'base',
    {
        _source: 'shared/common/manager',

        all:
        {
            _create: function()
            {
                this._super.apply(this, arguments);

                var widget = this.widget;
                var owner = widget.owner;

                this.heading = owner.child('div', 'heading');
                var heading = this.widget.getOption('heading');
                if (heading)
                    this.heading.text(IMu.string(heading));

                this.list = owner.child('div', 'list');

                if (widget.getOption('showAdd', false))
                {
                    var add = owner.child('div', 'add');
                    add.on('click', function()
                    {
                        widget.doAdd();
                    });

                    var image = add.child('img', 'image');
                    var url = IMu.Request.getURL('Image') + '&name=app/add';
                    image.attr('src', url);

                    var text = add.child('div', 'text')
                    var str = widget.getOption('addLabel', 'manager-add');
                    text.text(IMu.string(str));
                }

                this.update();
            },

            update: function()
            {
                this.list.empty();
                for (var i in this.widget.list)
                    this.updateItem(this.widget.list[i]);
            },

            updateItem: function(item)
            {
                var self = this;

                var row = self.list.child('div', 'item');

                var cell = row.child('div', 'title');
                cell.text(item.title);
                cell.on('click', function()
                {
                    self.widget.doUse(item);
                });

                cell = row.child('div', 'edit');
                if (item.permission == 'edit')
                {
                    var img = cell.child('img');
                    var url = IMu.Request.getURL('Image') + '&name=app/edit';
                    img.attr('src', url);

                    cell.on('click', function()
                    {
                        self.widget.doEdit(item);
                    });
                }
                else
                {
                    cell.html('&nbsp;');
                    cell.on('click', function()
                    {
                        self.widget.doUse(item);
                    });
                }

                cell = row.child('div', 'remove');
                if (item.permission == 'edit')
                {
                    var img = cell.child('img');
                    var url = IMu.Request.getURL('Image') + '&name=cross';
                    img.attr('src', url);

                    cell.on('click', function()
                    {
                        self.widget.doRemove(item);
                    });
                }
                else
                {
                    cell.html('&nbsp;');
                    cell.on('click', function()
                    {
                        self.widget.doUse(item);
                    });
                }
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/designer.js
*/
(function(theme)
{
    theme.views.register('designer', 'base',
    {
        _source: 'shared/common/designer',

        all:
        {
            _construct: function()
            {
                this._super.apply(this, arguments);

                this.holder = undefined;

                this.title = undefined;
                this.details = undefined;
                this.permissions = undefined;
                this.description = undefined;   // A brief description of the 
                                                // use of the final product

                this.tables = undefined;
                this.table = undefined;
            },

            _create: function()
            {
                this._super.apply(this, arguments);
                var self = this;

                var holder = self.holder = self.widget.owner.child('div', 'holder');
                holder.addClass('txt-colour-3');
                
                var title = self.title = holder.child('div', 'title');
                title.addClass('txt-colour-2');
            },

            addCollapsibleElement: function(owner, options)
            {
                if (! owner)
                    return;
                return _addCollapsibleElement(owner, options);
            },

            // private
            // 
            /*!
            ** Adds a new filter to an element in the designer.
            **
            ** Creates a form containing input fields for a column name and
            ** column value relating to conseptual element such as an attachment
            ** field or search.
            ** 
            ** When the page is built using either the `form-builder` or
            ** `editor-builder` any queries run by the element must also match 
            ** **all** of the filter terms added.
            **
            ** The column field will suggest values based on the table
            ** specified at the top of the designer.
            **
            ** @param owner
            **   The jQuery element in which to create the filter.
            **
            ** @param info
            **   An array containing two elements: column and value.
            **   If this parameter is specified, the column and value input
            **   fields will be filled in on creation.
            */
            addFilter: function(owner, info)
            {
                if (! owner)
                    return;
                var self = this;

                var table = self.details.getValue('table');
                var terms = undefined;
                if (info)
                {
                    if (info.table != undefined)
                        table = info.table;
                    terms = info.terms;
                }

                var holder = owner.children('.holder');
                var filter = holder.child('div', 'filter');
                var form = filter.IMu('form',
                {
                    rows: 1
                });
                form.addField('text',
                {
                    name: 'column',
                    label: 'designer-filter-column',
                    suggest: function(suggest, prefix, callback)
                    {
                        if (! table)
                        {
                            callback([]);
                            return;
                        }
                        var request = new IMu.Request.Schema();
                        request.getColumns(table, prefix, function(list)
                        {
                            callback(list);
                        });
                    }
                });
                form.addField('text',
                {
                    name: 'value',
                    label: 'designer-filter-value'
                });
                form.addField('empty');
                form.createView();

                form.view.table.find('td:nth-last-child(1)').each(function()
                {
                    jQuery(this).addClass('column-remove');
                    var remove = jQuery(this).child('div', 'filter-remove');
                    var button = remove.IMu('button-control');
                    button.addState(
                    {
                        layout:
                        [
                            {
                                type: 'image',
                                value: IMu.Request.getURL('Image')
                                    + '&name=cross'
                            }
                        ],
                        onClick: function()
                        {
                            filter.remove()
                        }
                    });
                    button.createView();
                });

                if (terms)
                {
                    var values =
                    {
                        'column': terms[0],
                        'value': terms[1]
                    };
                    form.setValues(values);
                }

                return filter;
            },

            /*!
            ** Adds additional user or group specific permissions.
            **
            ** @param level
            **   Either **user** or **group**.
            **
            ** @param name
            **   The name of the user or group that the permission applies to.
            **
            ** @param permission
            **   What permission the user or group has for the form or editor.
            **   This can be either:
            **   * edit
            **   * use
            **   * none
            */
            addPermission: function(level, name, permission)
            {
                var self = this;
                
                var additional = 
                    self.permissions.content.children('.additional')
                additional.css('display', 'block');

                var grid = 
                    self.permissions.content.find('.additional > .grid');
                var widget = grid.IMu();

                var values = {};
                if (level)
                    values.level = level;
                if (name)
                    values.name = name;
                if (permission)
                    values.permission = permission;
                values.remove = 1;

                var row = widget.appendRow(values);
                var remove = row.getCellByName('remove');
                var image = jQuery(remove.widget.view.icon);
                image.on('click', function()
                {
                    row.remove();
                    if (widget.rows.length == 0)
                        additional.css('display', 'none');
                });
            },

            /*!
            ** Creates a section of grouped elements.
            **
            ** Creates a div containing a title area, field area and filter area.
            ** The section can be rearranged with other sections via drag and
            ** drop, toggled open/closed and removed entirely.
            **
            ** @param sectionHeading
            **   The label for the section when it is built or toggled closed.
            **   If this parameter is passed, the label will be filled on
            **   creation.
            **
            ** @returns section
            **   The div created to represent the section.
            */
            // Kept for statistics-designer, which has not been converted to using
            // collapsible groups yet.
            addSection: function(sectionHeading)
            {
                var self = this;

                var section = self.sections.child('div', 'section');
                section.addClass('border-2');

                var title = section.child('div', 'title');
                title.addClass('bg-colour-2');
                var tr = title.child('table').child('tbody').child('tr');

                var label = tr.child('td', 'label');
                label.css('width', '99%');
                label.text(IMu.string(sectionHeading));

                tr.child('td', 'padding');

                var toggle = tr.child('td', 'toggle');
                toggle.css('width', '1%');
                var sectionToggle = toggle.child('div', 'section-toggle');
                section.add = undefined;
                section.holder = undefined;
                var button = sectionToggle.IMu('button-control');
                button.addState(
                {
                    name: 'opened',
                    layout:
                    {
                        type: 'image',
                        value: IMu.Request.getURL('Image') + '&name=arrow_u'
                    },
                    onClick: function()
                    {
                        if (holder !== undefined )
                        {
                            holder.css('display', 'none');
                            this.setState('closed');
                        }
                    }
                });
                button.addState(
                {
                    name: 'closed',
                    layout:
                    {
                        type: 'image',
                        value: IMu.Request.getURL('Image') + '&name=arrow_d'
                    },
                    onClick: function()
                    {
                        if (holder !== undefined)
                        {
                            holder.css('display', 'block');
                            this.setState('opened');
                        }
                    }
                });
                button.createView();

                var holder = section.child('div', 'holder');
                holder.addClass('bg-colour-1');

                var details = section.holder = holder.child('div', 'details');
                details.addClass('bg-colour-2');

                /* Section terms
                */
                var filters = self.makeFilters(holder);
                section[0].filters = filters;

                return section;
            },

            /*!
            ** Checks that a valid table has been set for the designer.
            **
            ** If the table is invalid or a new value, table specific values
            ** such as column names are cleared.
            */
            checkTable: function()
            {
                var self = this;

                self.loadTables(function(tables)
                {
                    var table = undefined;
                    var check = self.details.getValue('table');
                    if (check)
                    {
                        check = check.toLowerCase();
                        for (var i in tables)
                        {
                            if (tables[i].toLowerCase() == check)
                            {
                                table = tables[i];
                                break;
                            }
                        }
                    }
                    if (table)
                    {
                        self.details.setValue('table', table);
                        if (self.table && self.table != table)
                            self.clearColumns();
                        self.enableColumns(true);
                    }
                    else
                    {
                        self.details.setValue('table', '');
                        self.clearColumns();
                        self.enableColumns(false);
                    }
                    self.table = table;
                });
            },

            /*!
            ** Clears all input relating to field columns.
            */
            clearColumns: function()
            {
                var fields = this.getColumns();
                for (var i in fields)
                    fields[i].widget.setValue('');
            },

            /*!
            ** Clears all input in the details section.
            */
            clearDetails: function()
            {
                this.details.clearForm();
            },

            /*!
            ** Removes all filters in a jQuery element.
            **
            ** @param owner
            **   The jQuery element in which to find filters.
            */
            clearFilters: function(owner)
            {
                if (! owner)
                    return;

                var filterElems = owner.find('.filter').each(function()
                {
                    var filterElem = jQuery(this);
                    filterElem.remove();
                });
            },

            /*!
            ** Resets the designer permission to default.
            */
            clearPermissions: function()
            {
                var holder = this.permissions.content;

                var everyone = holder.children('.everyone').IMu();
                var permission = 'none';
                everyone.setValue('permission', permission);

                var additional = holder.find('.additional > .grid').IMu();
                additional.clearGrid();
                holder.children('.additional').css('display', 'none');
            },

            /*!
            ** Toggles write access on columns.
            */
            enableColumns: function(enable)
            {
                var fields = this.getColumns();
                for (var i in fields)
                    fields[i].widget.setOption('readonly', ! enable);
            },
            
            /*!
            ** Gets all filters in a jQuery element.
            **
            ** Extracts filter information for a conceptual element in the
            ** designer and adds the results to ``info``.
            ** 
            ** @param owner
            **   The jQuery element in which to find filters.
            **
            ** @param info
            **   A hash representing the structure of the designer.
            **
            ** @returns terms
            **   An array of column and value pairs, each representing a filter
            **   term.
            */
            getFilters: function(owner, info)
            {
                var terms = [];
                var filterElems = owner.find('.filter').each(function()
                {
                    var filterElem = jQuery(this);
                    var filter = filterElem.IMu().getValues();
                    if (filter.column != null && filter.value != null)
                        terms.push([filter.column, filter.value, null]);
                });
                if (terms.length > 0 && info)
                    info.filter = { "terms": terms };

                return terms;
            },

            /*!
            ** Gets the permmissions for a designer and stores it in ``form``.
            **
            ** @param form
            **   A hash representation of the designer.
            */
            getPermissions: function(form)
            {
                form.permissions = {};

                var holder = this.permissions.content;

                var everyone = holder.children('.everyone').IMu();
                var permission = everyone.getValue('permission');
                form.permissions.everyone = permission;
                
                var additional = holder.find('.additional > .grid').IMu();
                var values = additional.getValues();
                for (var i in values)
                {
                    var additional = {};

                    var row = values[i];

                    additional.level = row.level;
                    additional.name = row.name;
                    if (! additional.name)
                        continue;
                    additional.permission = row.permission;

                    if (! form.permissions.additional)
                        form.permissions.additional = [];
                    form.permissions.additional.push(additional);
                }
            },

            /*!
            ** Loads a list of table names from the schema.
            **
            ** @param callback function
            **  The function to be called once tables are loaded.
            **  Takes a list of tables as a parameter.
            */
            loadTables: function(callback)
            {
                if (self.tables)
                {
                    callback(self.tables);
                    return;
                }
                var request = new IMu.Request.Schema();
                request.getTables(function(tables)
                {
                    self.tables = tables;
                    callback(self.tables);
                });
            },

            /*!
            ** Creates a set of buttons at the bottom of the page.
            **
            ** Creates save, cancel and exit buttons at the bottom of the page 
            ** based on the `designer` widget's options. 
            */
            makeButtons: function()
            {
                var self = this;

                // Cancel and Save
                //
                var save = self.widget.getOption('showSave', true);
                var cancel = self.widget.getOption('showCancel', true);
                var exit = self.widget.getOption('showExit', true);

                if (save || cancel || exit)
                {
                    var buttons = self.widget.owner.child('div');
                    buttons.addClass('buttons');

                    if (save)
                    {
                        var button = self.cancel = buttons.child('div', 
                            'save').IMu('button-control');
                        button.addState(
                        {
                            layout:
                            {
                                type: 'text',
                                value: IMu.string('designer-save')
                            },
                            onClick: function()
                            {
                                self.widget.validate(function(info)
                                {
                                    self.widget.doSave(self.widget.getDesigner());
                                });
                            },
                            classes: 'bg-colour-3 txt-colour-1'
                        });
                        button.createView();
                    }
                    if (cancel)
                    {
                        var button = self. cancel = buttons.child('div', 
                            'cancel').IMu('button-control');
                        button.addState(
                        {
                            layout:
                            {
                                type: 'text',
                                value: IMu.string('designer-cancel')
                            },
                            onClick: function()
                            {
                                self.widget.doCancel();
                            },
                            classes: 'bg-colour-3 txt-colour-1'
                        });
                        button.createView();
                    }
                    if (exit)
                    {
                        var button = self.exit = buttons.child('div',
                            'exit').IMu('button-control');
                        button.addState(
                        {
                            layout:
                            {
                                type: 'text',
                                value: IMu.string('designer-exit')
                            },
                            onClick: function()
                            {
                                self.widget.doExit();
                            },
                            classes: 'bg-colour-3 txt-colour-1'
                        });
                        button.createView();
                    }
                }
            },

            /*!
            ** Creates an area for filters to be added.
            **
            ** @param owner
            **   The element in which to create the filter area.
            */
            makeFilters: function(owner)
            {
                var self = this;

                if (! owner)
                    var owner = self.holder;

                var filters = owner.child('div', 'filters');

                var title = filters.child('div', 'title');
                title.addClass('txt-colour-3');
                var tr = title.child('table').child('tbody').child('tr');

                var label = tr.child('td', 'label');
                label.css('width', '99%');
                label.text(IMu.string('designer-filters'));
                
                var holder = filters.child('div', 'holder');
                var add = owner.child('div', 'holder').child('div', 'add');
                add.on('click', function()
                {
                    var form  =  owner.children('.form').IMu();
                    if (form && form.getValue('table') != undefined)
                        self.addFilter(filters, {table: form.getValue('table')});
                    else
                        self.addFilter(filters);
                });
                filters.addButton = add;

                var image = add.child('img', 'image');
                var url = IMu.Request.getURL('Image') + '&name=app/add';
                image.attr('src', url);

                var text = add.child('div', 'text');
                text.text(IMu.string('designer-add-filter-term'));

                // helps with having multiple filter sections
                filters.clearFilters = function()
                {
                    self.clearFilters(filters);
                };
                filters.getFilters = function(info)
                {
                    return self.getFilters(filters, info);
                };
                filters.setFilters = function(info)
                {
                    if (! info)
                        return;
                    
                    if (info.terms == undefined && IMu.Type.isArray(info))
                        self.setFilters(filters, info);
                    else
                        self.setFilters(filters, info.terms, info.table);
                };

                return filters;
            },
            
            /*!
            ** Creates the permissions section.
            **
            ** Creates a selection box to control the most basic permissions for
            ** the form/editor. This is the fallback permission level for users 
            ** and groups that do not have permissions specified.
            **
            ** Creates a button to add additional user or group permissions.
            */
            makePermissions: function(info)
            {
                var self = this;

                var permissions = self.permissions =
                    self.addCollapsibleElement(self.holder,
                {
                    "class": 'permissions bg-colour-1 border-3',
                    header:
                    {
                        icon: 'app/permissions_white',
                        label: 'designer-permissions',
                        "class": 'bg-colour-3 txt-colour-1'
                    },
                    toggle:
                    {
                        openIcon: 'arrow_white_u',
                        closedIcon: 'arrow_white_d'
                    }
                });

                var everyone = permissions.content.child('div', 
                    'everyone bg-colour-1');
                everyone = everyone.IMu('form');
                everyone.addField('selection',
                {
                    name: 'permission',
                    label: 'designer-permissions-everyone',
                    list:
                    [
                        'edit',
                        'none',
                        'use'
                    ]
                });
                everyone.createView();

                var additional = permissions.content.child('div', 'additional');
                additional.addClass('bg-colour-2');

                var title = additional.child('div', 'title bg-colour-3 txt-colour-1');
                var tr = title.child('table').child('tbody').child('tr');
                var label = tr.child('td', 'label');
                label.text(IMu.string('designer-permissions-additional'));
                tr.child('td', 'padding');

                // TODO: these are really lame column names
                var grid = additional.child('div', 'grid');
                var widget = grid.IMu('grid');
                widget.addColumn('selection',
                {
                    name: 'level',
                    list:
                    [
                        'user',
                        'group'
                    ],
                    onChange: function(cell, value)
                    {
                        var name = cell.row.getCellByName('name');
                        name.setValue('');
                    }
                });
                widget.addColumn('text',
                {
                    name: 'name',
                    suggest: function(suggest, prefix, callback)
                    {
                        var row = this.cell.row;
                        var values = row.getValues();
                        var level = values.level;

                        var request = new IMu.Request.Access();
                        if (level == 'group')
                            request.getGroups(prefix, callback);
                        else if (level == 'user')
                            request.getUsers(prefix, callback);
                        else
                            callback([]);
                    }
                });
                widget.addColumn('selection',
                {
                    name: 'permission',
                    list:
                    [
                        'edit',
                        'none',
                        'use'
                    ]
                });
                widget.addColumn('icon',
                {
                    name: 'remove',
                    icons:
                    {
                        1: 'cross'
                    }
                });
                widget.createView();

                var add = permissions.content.child('div', 'add');
                add.on('click', function()
                {
                    self.addPermission();
                });

                var image = add.child('img', 'image');
                var url = IMu.Request.getURL('Image') + '&name=app/add';
                image.attr('src', url);

                var text = add.child('div', 'text');
                text.text(IMu.string('designer-add-permission'));

                return permissions;
            },

            /*!
            ** Sets filters for a section.
            **
            ** This function serves two purposes:
            ** 1) Loading filters into a designer
            ** 2) Creating a new filter that uses an alternate table to the
            ** designer.
            **
            ** @param owner
            **   The jQuery element which to add filters to.
            **
            ** @param terms
            **   An array of column names and values to be loaded.
            **   If this parameter is passed, filters created will have values
            **   set upon creation.
            **
            ** @param table
            **   The name of the table to get column name suggestions from.
            **   If this parameter is passed, filter column names will auto
            **   suggest columns from this table.
            */
            setFilters: function(owner, terms, table)
            {
                for (var i in terms)
                {
                    if (terms[i].length == 2);
                        this.addFilter(owner, {terms: terms[i], table: table});
                }
            },
            
            /*!
            ** Loads permissions from the designer information.
            **
            ** @param form
            **   A hash representation of the designer.
            */
            setPermissions: function(form)
            {
                var holder = this.permissions.content;

                var everyone = holder.children('.everyone').IMu();
                var permission = 'none';
                if (form.permissions && form.permissions.everyone)
                    permission = form.permissions.everyone;
                everyone.setValue('permission', permission);

                if (form.permissions && form.permissions.additional)
                    for (var i in form.permissions.additional)
                    {
                        var additional = form.permissions.additional[i];
                        var level = additional.level;
                        var name = additional.name;
                        var permission = additional.permission;
                        this.addPermission(level, name, permission);
                    }
            }
        }
    });

    /* Private functions
    */
    var _addCollapsibleElement = function(owner, options)
    {
        var element = owner.child('div', 'collapsible-group');
        var header = element.child('div', 'title');
        var content = element.child('div', 'holder');

        if (options)
        {
            if (options["class"])
                element.addClass(options["class"]);
            if (options.id)
                element.attr('id', options.id);

            if (options.content)
            {
                if (options.content["class"])
                    content.addClass(options.content["class"]);
                if (options.content.id)
                    content.attr('id', options.content.id);
            }
        }

        _makeCollapsibleHeader(element, header, content, options);
        var details = _makeCollapsibleDetails(content, options);

        return {
            element: element,
            header: header,
            details: details,
            content: content
        };
    };

    var _makeCollapsibleHeader = function(owner, header, content, options)
    {
        var tr = header.child('table').child('tbody').child('tr');

        var icon = tr.child('td', 'icon');
        var label = tr.child('td', 'label');
        var remove = tr.child('td', 'remove');
        remove.css('width', '1%');
        var toggle = tr.child('td', 'toggle');
        toggle.css('width', '1%');

        if (options)
        {
            if (options.header)
            {
                if (options.header["class"])
                    header.addClass(options.header["class"]);
                if (options.header.id)
                    header.attr('id', options.header.id);

                if (options.header.icon)
                {
                    var img = icon.child('img');
                    var src = IMu.Request.getURL('Image') + '&name=';
                    src += options.header.icon;
                    img.attr('src', src);
                }
                else
                    icon.hide();

                if (options.header.label)
                    label.text(IMu.string(options.header.label));
                else
                    label.text('');
            }

            if (options.removeable)
            {
                var button = remove.child('div');
                button.addClass('section-remove');

                var image = "cross";
                if (header.hasClass('bg-colour-3'))
                    image += "_white";

                button = button.IMu('button-control');
                button.addState
                ({
                    layout:
                    [
                        {
                            type: 'image',
                            value: IMu.Request.getURL('Image') + '&name=' + image
                        }
                        /* Add if client wants text for the remove button 
                        {
                            type: 'text',
                            value: IMu.string('form-designer-remove')
                        }
                        */
                    ],
                    onClick: function()
                    {
                        if (options.onRemove &&
                            typeof(options.onRemove) == 'function')
                            options.onRemove();
                        owner.remove();
                    }
                });
                button.createView();
            }

            if (options.toggle)
            {
                var tOptions = options.toggle;
                var button = toggle.child('div');
                button.addClass('section-toggle');

                button = button.IMu('button-control');
                button.addState
                ({
                    name: 'opened',
                    layout:
                    {
                        type: 'image',
                        value: IMu.Request.getURL('Image') + '&name=' +
                            tOptions.openIcon
                    },
                    onClick: function()
                    {
                        this.setState('closed');
                        content.hide();
                        if (tOptions.onToggledClosed)
                            tOptions.onToggledClosed();
                    }
                });
                button.addState
                ({
                    name: 'closed',
                    layout:
                    {
                        type: 'image',
                        value: IMu.Request.getURL('Image') + '&name=' +
                            tOptions.closedIcon
                    },
                    onClick: function()
                    {
                        this.setState('opened');
                        content.show();
                        if (tOptions.onToggledOpen)
                            tOptions.onToggledOpen();
                    }
                });
                button.createView();

                if (tOptions.closed)
                    button.onClick();
            }
        }
    };

    var _makeCollapsibleDetails = function(owner, options)
    {
        if (! options || ! options.details)
            return;

        var details = owner.child('div', 'details');

        if (options.details["class"])
            details.addClass(options.details["class"]);
        if (options.details.id)
            details.attr('id', options.details.id);

        if (options.details.fields)
        {
            var form;
            if (options.details.options)
                form = details.IMu('form', options.details.options);
            else
                form = details.IMu('form');

            var fields = options.details.fields;

            var type, fieldOpts;

            for (var i = 0; i < fields.length; i++)
            {
                var field = fields[i];
                type = field.type? field.type : 'text';
                fieldOpts = field.options ? field.options : {};

                var field = form.addField(type, fieldOpts);
                if (fieldOpts.name)
                    details[fieldOpts.name] = field;

            }
            form.createView();

            var values = options.details.info;
            if (values)
                form.setValues(values);

            return form;
        }
    };
})(IMu.Themes.shared);

/* Source: ./shared/common/views/editor-builder.js
*/
(function(theme)
{
    theme.views.register('editor-builder', 'base',
    {
        _source: 'shared/common/editor-builder',

        all:
        {
            _construct: function()
            {
                var self = this;

                self._super.apply(self, arguments);

                this.sourceInput = undefined;
            },

            _create: function()
            {
                var self = this;

                self._super();

                // var owner = self.widget.owner;
                var owner = self.widget.owner.child('div', 'owner', 'bg-colour-2');

                if (!self.widget.destination)
                    self.widget.destination = {};

                if (!self.widget.source)
                    self.widget.source = {};

                self.widget.source.holder = owner.child('div', 'imu-source-owner section');;
                var source = self.widget.source.holder;

                self.widget.destination.holder = owner.child('div', 'imu-destination-owner section');

                var sourceInput = self.sourceInput = source.child('div', 'input');
                var field  = sourceInput.IMu('text-control',
                {
                    hint: 'Source',
                    onEnter: function()
                    {
                        self.clearSource();
                        
                        self.widget.doFetchSource(this.value,function(result)
                        {
                            self.updateSelect(result, self.widget.source.selection);
                        });

                    }
                });

                if (! field.view)
                    field.createView();
                field.view.control.blur();

                var sourceSelection = source.child('div', 'selection')
                var selection = sourceSelection.child('select', 'select');
                selection.attr('size', 10);
                selection.attr('multiple', 'multiple');

                self.widget.source.selection = selection;

                if (self.widget.options.method == 'attach')
                    self.createAttachmentDestination();
                else if (self.widget.options.method == 'replace')
                {
                    var field = self.widget.field;

                    if (field.type == 'text')
                        self.createTextDestination(field);
                    else if (field.type == 'date')
                        self.createDateDestination();
                }

                var options = self.widget.getOption('editorOptions')
                if (options)
                    self.widget.configure(options);

                // Cancel and Save
                //
                var update = self.widget.getOption('showUpdate', 'true');
                if (update)
                {
                    var buttons = self.widget.owner.child('div');
                    buttons.addClass('buttons');
                    var holder = buttons.child('div', 'holder');

                    if (update)
                    {
                        var button = self.update = holder.child('div',
                            'update').IMu('button-control');
                        button.addState(
                        {
                            layout:
                            {
                                type: 'text',
                                value: IMu.string('editor-builder-update')
                            },
                            onClick: function()
                            {
                                self.widget.validate(function(info)
                                {
                                    self.widget.doUpdate(function(result)
                                    {
                                        if (self.widget.options.onlyEmpty == true)
                                        {                                    
                                            self.clearSource();

                                            var val = self.sourceInput.IMu().value;
                            
                                            self.widget.doFetchSource(val,function(result)
                                            {
                                                self.updateSelect(result, self.widget.source.selection);
                                            });
                                        }
                                    });
                                });
                            },
                            classes: 'bg-colour-3 txt-colour-1'
                        });
                        button.createView();
                    }
                }
            },

            createAttachmentDestination: function()
            {
                var self = this;
                var destination = self.widget.destination.holder;

                var destinationInput = destination.child('div', 'input');
                var field = destinationInput.IMu('text-control',
                {
                    hint: 'Target',
                    onEnter: function()
                    {
                        self.clearDestination();
                        
                        self.widget.doFetchDestination(this.value, function(result)
                        {
                            self.updateSelect(result, self.widget.destination.selection);
                        }); 
                        
                    }
                });
                if (!field.view)
                    field.createView();
                field.view.control.blur();

                var destinationSelection = destination.child('div', 'selection');
                var selection = destinationSelection.child('select', 'select');
                selection.attr('size', 10);

                self.widget.destination.selection = selection;
            },

            createDateDestination: function()
            {
                var destination = this.widget.destination.holder;
                var destinationInput = destination.child('div', 'input');

                var field = this.widget.destination.inputField = 
                    destinationInput.IMu('date-control',
                {
                    hint: 'Target',
                    picker: true
                });

                if (!field.view)
                    field.createView();
                field.view.control.blur();
            },

            clearDestination: function()
            {
                if (this.widget.destination.selection)
                    this.widget.destination.selection.empty();
            },

            clearSource: function()
            {
                if (this.widget.source.selection)
                    this.widget.source.selection.empty();
            },

            createTextDestination: function(field)
            {
                var destination = this.widget.destination.holder;
                var destinationInput = destination.child('div', 'input');

                var field = this.widget.destination.inputField = destinationInput.IMu('text-control',
                {
                    hint: 'Target',
                    suggest: field.suggest
                });

                if (!field.view)
                    field.createView();
                field.view.control.blur();
            },

            updateSelect: function(data, selector)
            {
                if (selector)
                    selector.empty();

                for (var i = 0; i < data.length; i++)
                {
                    var option = selector.child('option');
                    var text = data[i].value;
                    var string = "";

                    if (text)
                        string = text;
                    else if (text == "")
                        string = "NULL";
                    if (data[i].irns)
                    {
                        string += ' (' + data[i].irns.length + ')';
                        //option.val(data[i].count);
                    }
                    if (data[i].irns)
                        option.val(data[i].irns);
                    else if (data[i].val)
                        option.val(data[i].val);

                    option.text(string);
                }
            }
        }
    });
})(IMu.Themes.shared);

/* Source: ./shared/common/views/editor-designer.js
*/
(function(theme)
{
    theme.views.register('editor-designer', 'designer',
    {
        _source: 'shared/common/editor-designer',

        all:
        {
            _construct: function()
            {
                this._super.apply(this, arguments);

                this.source = undefined;
                this.destination = undefined;
            },

            _create: function()
            {
                this._super.apply(this, arguments);

                this.makeDetails();
                this.makePermissions();
                this.sections = this.holder.child('div', 'sections');
                this.makeSource();
                this.makeDestination();
                this.makeButtons();
                this.newEditor();
            },

            /*!
            ** Clears all data from the `editor-designer`.
            */
            clearEditor: function()
            {
                this.title.text('');
                this.clearDetails();
                this.clearPermissions();
                this.source.clearForm();
                this.destination.clearForm();
                this.clearTerms();
            },

            /*!
            ** Creates a hash representation of the editor.
            **
            ** @returns editor
            **   The hash representation of the editor.
            */
            getEditor: function()
            {
                var self = this;

                var editor = {};
                var config = editor.config = {};
                var options = editor.options = {};

                var detailValues = self.details.getValues();
                var sourceValues = self.source.getValues();
                var destinationValues = self.destination.getValues();

                if(detailValues.id)
                    self.widget.id = detailValues.id;

                if(detailValues.title)
                    editor.title = detailValues.title;
                
                if(detailValues.description)
                    editor.description = detailValues.description;

                //PERMISSION
                //
                self.getPermissions(editor);

                //OPTIONS
                //
                if(self.method)
                    options.method = self.method;
                if(destinationValues.onlyEmpty)
                    options.onlyEmpty = destinationValues.onlyEmpty;
                else
                    options.onlyEmpty = false;

                //CONFIG
                //
                if(detailValues.table)
                    config.sourceTable = detailValues.table;
                if(sourceValues.column)
                    config.sourceColumn = sourceValues.column;
                if(destinationValues.destinationTable)
                    config.destinationTable = destinationValues.destinationTable;
                if(destinationValues.column)
                    config.destinationColumn = destinationValues.column;
                if(destinationValues.attachmentColumn)
                    config.attachmentColumn = destinationValues.attachmentColumn;

                if(destinationValues.column && destinationValues.attachmentColumn)
                    options.method = 'attach';
                else
                    options.method = 'replace';

                // TERMS
                // 
                var sections = self.sections.children('.section');
                var sourceTerms = [];
                var destinationTerms = [];
                var length = sections.length;

                for (var i = 0; i < length; i++)
                {
                    var s = jQuery(sections[i]);
                    var terms = s.find('.terms').children('.term');

                    var t3 = sections[i].filters.getFilters();
                    if (t == undefined)
                        var t = [];
                    t.push(t3);
                    switch (i)
                    {
                        case 0:
                            sourceTerms = sections[i].filters.getFilters();
                            break;
                        case 1:
                            destinationTerms = sections[i].filters.getFilters();
                            break;
                    }
                }

                if(sourceTerms.length > 0)
                    config.sourceTerms = sourceTerms;
                if(destinationTerms.length > 0)
                    config.destinationTerms = destinationTerms;

                //REPLACE
                //
                if (self.method == 'replace')
                {
                    var replaceField = options.replaceField = {};

                    if(destinationValues.type)
                        replaceField.type = destinationValues.type;
                    if(destinationValues.hint)
                        replaceField.hint = destinationValues.hint;
                    if(destinationValues.name)
                    {
                        var suggest = replaceField.suggest = {};
                        suggest.type = 'lookup';
                        suggest.name = destinationValues.name;
                        if (destinationValues.level)
                        {
                            // assumes the user works with 1 based indexing
                            suggest.level = parseInt(destinationValues.level) -1;
                            suggest.level = suggest.level.toString();
                        }
                    }
                }

                return editor;
            },

            /*!
            ** Clears all values from the editor and sets the title.
            */
            newEditor: function()
            {
                this.clearEditor();
                this.title.text(IMu.string('editor-designer-new-form'));
            },

            /*!
            ** Sets values in the editor.
            **
            ** Once the editor information has loaded, the values are set.
            **
            ** @param editor
            **   A hash representation of the editor.
            */
            setEditor: function(editor)
            {
                var self = this;
                self.clearEditor();

                if(! editor)
                    return

                if(editor.method)
                    self.method = editor.method;

                //DETAILS
                //
                var values = {};

                if(self.widget.id && self.widget.id != '_')
                    values.id = self.widget.id;

                if(editor.title)
                    values.title = editor.title;

                if(editor.description)
                    values.description = editor.description;

                if(editor.config.sourceTable)
                    values.table = editor.config.sourceTable;

                self.details.setValues(values);

                self.details.getField('id').widget.setOption('readonly', true);

                //PERMISSIONS
                self.setPermissions(editor);

                //SOURCE
                //
                var values = {};
                if(editor.config.sourceColumn)
                    values.column = editor.config.sourceColumn;
                self.source.setValues(values);

                //DESTINATION
                //
                var values = {};
                if(editor.config.attachmentColumn)
                    values.attachmentColumn = editor.config.attachmentColumn;
                if(editor.options.onlyEmpty)
                    values.onlyEmpty = editor.options.onlyEmpty;
                if(editor.config.destinationColumn)
                    values.column = editor.config.destinationColumn;
                if(editor.config.destinationTable)
                    values.destinationTable = editor.config.destinationTable;

                if(editor.config.destinationColumn && editor.config.destinationTable)
                    self.method = 'attach';
                else
                    self.method = 'replace';

                if (editor.options.replaceField)
                {
                    var replaceField = editor.options.replaceField;
                    if(replaceField.type)
                        values.type = replaceField.type;
                    if(replaceField.hint)
                        values.hint = replaceField.hint;
                    if (replaceField.suggest)
                    {
                        var suggest = replaceField.suggest;
                        if (suggest.name)
                            values.name = suggest.name;
                        if (suggest.level)
                            // assumes the user works with 1 based indexing
                            values.level = parseInt(suggest.level) +1;
                    }
                }

                self.destination.setValues(values);

                //TERMS
                //
                var sections = self.sections.children('.section');
                if(editor.config.sourceTerms)
                {
                    var terms = editor.config.sourceTerms;
                    sections[0].filters.setFilters(terms);
                }
                
                if(editor.config.destinationTerms)
                {
                    var terms = editor.config.destinationTerms;
                    sections[1].filters.setFilters(terms);
                }

                self.checkTable();
            },

            /*!
            ** Clears all terms for source and destination sections.
            */
            clearTerms: function()
            {
                var sections = this.sections.children('.section');
                for (var i = 0; i < sections.length; i++)
                    sections[i].filters.clearFilters();
            },

            /*!
            **
            ** @returns list
            **   The list of columns.
            */
            getColumns: function()
            {
                var list = [];
                var forms = this.sections.find('.form');
                for (var i = 0; i < forms.length; i++)
                {
                    var form = jQuery(forms[i]).IMu();
                    if (! form)
                        continue;
                    var field = form.getField('column');
                    if (! field || ! field.widget)
                        continue;
                    list.push(field);
                }
                return list;
            },

            /*!
            ** Creates the data destination section.
            */
            makeDestination: function()
            {
                var self = this;

                var options =
                {
                    "class": 'section bg-colour-1 border-3',
                    header:
                    {
                        icon: 'app/destination_white',
                        label: 'editor-designer-destination-section',
                        "class": 'bg-colour-3 txt-colour-1'
                    },
                    details:
                    {
                        options:
                        {
                            columns: 2,
                            rows: 2,
                            onValidate: function(info, callback)
                            {
                                /* Uncomment if either
                                ** 1) Attachment field types become available
                                ** 2) Reference Column becomes modifiable

                                if (this.hash.table.getValue() == undefined &&
                                    this.hash.column.getValue() != undefined &&
                                    (this.hash.type.getValue() == "attachment" ||
                                    this.hash.refColumn.getValue() != undefined))
                                {
                                    this.updateValidationState(
                                        info, 'invalid');
                                    info.details.push(
                                    {
                                        info:
                                        {
                                            state: "invalid",
                                            details: "validation-type-not-ref-column"
                                        },
                                        field: this.hash.column.widget.view.control
                                    });
                                    this.hash.column.widget.setIcon("invalid",
                                        "designer-validation-type-not-ref-column");
                                }
                                */
                                if (this.hash.name.getValue() != undefined &&
                                    this.hash.level.getValue() == undefined)
                                {
                                    this.updateValidationState(
                                        info, "invalid");
                                    info.details.push(
                                    {
                                        info:
                                        {
                                            state: "invalid",
                                            details: "validation-empty-mandatory"
                                        },
                                        field: this.hash.level.widget.view.control
                                    });
                                    this.hash.level.widget.setIcon("invalid",
                                        "validation-empty-mandatory");
                                }
                                else if (this.hash.name.getValue() == undefined &&
                                    this.hash.level.getValue() != undefined)
                                {
                                    this.updateValidationState(
                                        info, "invalid");
                                    info.details.push(
                                    {
                                        info:
                                        {
                                            state: "invalid",
                                            details: "validation-empty-mandatory"
                                        },
                                        field: this.hash.name.widget.view.control
                                    });
                                    this.hash.name.widget.setIcon("invalid",
                                        "validation-empty-mandatory");
                                }
                                callback(info);
                            },
                            order: 'row',
                            validateOnChange: true
                        },
                        fields:
                        [
                            {
                                type: 'text',
                                options:
                                {
                                    name: 'attachmentColumn',
                                    label: 'editor-designer-destination-column',
                                    requirement: 'mandatory',
                                    suggest:
                                    {
                                        type: 'function',
                                        code: function(suggest, prefix, callback)
                                        {
                                            var table = self.details.getValue('table');
                                            if (! table)
                                            {
                                                callback([]);
                                                return;
                                            }
                                            var request = new IMu.Request.Schema();
                                            request.getColumns(table, prefix, function(list)
                                            {
                                                callback(list);
                                            });
                                        },
                                        onSelect: function()
                                        {
                                            var prefix = this.getValue()
                                            var table = self.details.getValue('table');

                                            var request = new IMu.Request.Schema();
                                            request.getColumn(table, prefix, function(result)
                                            {
                                                var destinationTable = 
                                                    self.destination
                                                    .hash.destinationTable;
                                                var destinationColumn =
                                                    self.destination
                                                    .hash.column;
                                                var replaceType = 
                                                    self.destination
                                                    .hash.type;
                                                if (! result.RefTable)
                                                {
                                                    self.method = 'replace';
                                                    destinationTable.setValue('');
                                                    destinationColumn.setValue('');

                                                    replaceType.setValue(
                                                        result.DataType.toLowerCase());
                                                    return;
                                                }
                                                self.method = 'attach';
                                                destinationTable.setValue(result.RefTable);
                                                destinationColumn.setValue('SummaryData');
                                            });
                                        }
                                    },
                                    onChange: function()
                                    {
                                        // TODO
                                        var destinationTable = 
                                            self.destination.hash.destinationTable;
                                        var destinationColumn =
                                            self.destination.hash.column;

                                        destinationTable.setValue('');
                                        destinationColumn.setValue('');
                                    },
                                    onLoseFocus: function()
                                    {
                                        this.suggest.onSelect.call(this);
                                    },
                                    validateOnChange: true
                                }
                            },
                            {
                                type: 'checkbox',
                                options:
                                {
                                    name: 'onlyEmpty',
                                    label: 'editor-designer-only-empty',
                                    validateOnChange: true
                                }
                            },
                            {
                                type: 'text',
                                options:
                                {
                                    name: 'destinationTable',
                                    label: 'editor-designer-reference-table',
                                    readonly: true,
                                    validateOnChange: true
                                }
                            },
                            {
                                type: 'text',
                                options:
                                {
                                    name: 'column',
                                    label: 'editor-designer-reference-column',
                                    readonly: true,
                                    validateOnChange: true
                                }
                            },
                            {
                                type: 'selection',
                                options:
                                {
                                    name: 'type',
                                    label: 'editor-designer-replace-type',
                                    list:
                                    [
                                        'text',
                                        'date'
                                    ],
                                    validateOnChange: true
                                }
                            },
                            {
                                type: 'text',
                                options:
                                {
                                    name: 'hint',
                                    label: 'editor-designer-replace-hint',
                                    validateOnChange: true
                                }
                            },
                            {
                                type: 'text',
                                options:
                                {
                                    name: 'name',
                                    label: 'editor-designer-lookup-name',
                                    suggest:
                                    {
                                        type: 'lookup',
                                        name: 'Lookup Name',
                                        level: 0,
                                        onSelect: function()
                                        {
                                            level.setValue('1');
                                        }
                                    },
                                    onChange: function()
                                    {
                                        level.setValue('');
                                    },
                                    validateOnChange: true
                                }
                            },
                            {
                                type: 'text',
                                options:
                                {
                                    name: 'level',
                                    label: 'editor-designer-lookup-level',
                                    validateOnChange: true
                                }
                            }
                        ]
                    },
                    toggle:
                    {
                        openIcon: 'arrow_white_u',
                        closedIcon: 'arrow_white_d'
                    },
                    removeable: false
                };

                var section = self.addCollapsibleElement(self.sections, options);
                var destination = self.destination = section.details;
                var filters = self.makeFilters(section.content);
                section.element[0].filters = filters;
            },

            /*!
            ** Creates the editor details section.
            */
            makeDetails: function()
            {
                var self = this;
                
                var details = self.holder.child('div', 'details');

                details.addClass('txt-colour-inherit ' +
                    'bg-colour-1 border-4');

                details = self.details = details.IMu('form',
                {
                    columns: 2,
                    order: 'row'
                });

                details.addField('text',
                {
                    name: 'title',
                    label: 'editor-designer-title',
                    requirement: 'suggested',
                    validateOnChange: true,
                    columnSpan: 2
                });

                details.addField('text',
                {
                    name: 'description',
                    label: 'editor-designer-description',
                    validateOnChange: false,
                    lines: 2,
                    columnSpan: 2
                });

                details.addField('text',
                {
                    name: 'id',
                    label: 'editor-designer-id',
                    validateOnChange: true
                });

                details.addField('text',
                {
                    name: 'table',
                    label: 'editor-designer-table',
                    requirement: 'mandatory',
                    suggest:
                    {
                        type: 'function',
                        code: function(suggest, prefix, callback)
                        {
                            self.loadTables(function(tables)
                            {
                                var list = [];
                                var regex = new RegExp('^' + prefix, 'i');
                                for (var i in tables)
                                {
                                    var table = tables[i];
                                    if (table.match(regex))
                                        list.push(table);
                                }
                                callback(list);
                            });
                        }
                    },
                    onLoseFocus: function()
                    {
                        self.checkTable();
                    },
                    validateOnChange: true
                });
                
                details.createView();
            },

            /*!
            ** Creates the data source section.
            */
            makeSource: function()
            {
                var self = this;

                var options =
                {
                    "class": 'section bg-colour-1 border-3',
                    header:
                    {
                        icon: 'app/source_white',
                        label: 'editor-designer-source-section',
                        "class": 'bg-colour-3 txt-colour-1'
                    },
                    details:
                    {
                        fields:
                        [
                            {
                                type: 'text',
                                options:
                                {
                                    name: 'column',
                                    label: 'editor-designer-source-column',
                                    requirement: 'mandatory',
                                    suggest: function(suggest, prefix, callback)
                                    {
                                        var table = self.details.getValue('table')
                                        if (! table)
                                        {
                                            callback([]);
                                            return;
                                        }
                                        var request = new IMu.Request.Schema();
                                        request.getColumns(table, prefix, function(list)
                                        {
                                            callback(list);
                                        });
                                    },
                                    validateOnChange: true

                                }
                            }
                        ]
                    },
                    toggle:
                    {
                        openIcon: 'arrow_white_u',
                        closedIcon: 'arrow_white_d'
                    },
                    removeable: false
                };
                var section = self.addCollapsibleElement(self.sections, options);
                var source = self.source = section.details;
                var filters = self.makeFilters(section.content)
                section.element[0].filters = filters;
            }
        }
    });
})(IMu.Themes.shared);

